// What the append composer's editor offers as you type, as pure functions over the draft's text: an
// event's four fields at the start of a mapping, and after `type:` the event types this context
// knows — the ones some processor here consumes, then the ones in the loaded log, most frequent
// first.
import { shortEventType } from "./filters.tsx";
import type { CodeEditorCompletions } from "#/components/code-editor.client.tsx";

/** One event type the composer can offer, with why it is known. */
export type KnownEventType = { type: string; detail: string; section: string };

/** Every type a processor here consumes (wildcards name no one type) and every type in the log,
 *  each once: consumed first (by name), then the log's by count. */
export function knownEventTypes(
  counts: readonly [type: string, count: number][],
  processors: readonly { name: string; consumes?: readonly string[] }[],
): KnownEventType[] {
  const consumers = new Map<string, string[]>();
  for (const processor of processors)
    for (const type of processor.consumes || [])
      if (!type.includes("*"))
        consumers.set(type, [...(consumers.get(type) || []), processor.name]);
  const inLog = new Map(counts);
  const known: KnownEventType[] = [...consumers.keys()].sort().map((type) => ({
    type,
    section: "Consumed here",
    detail: `${consumers.get(type)!.join(", ")}${inLog.has(type) ? ` · ${inLogCount(inLog.get(type)!)}` : ""}`,
  }));
  for (const [type, count] of counts)
    if (!consumers.has(type))
      known.push({ type, section: "In the log", detail: inLogCount(count) });
  return known;
}

const inLogCount = (count: number) => `${count.toLocaleString()} in the log`;

const FIELDS = [
  { key: "type", detail: "the event type" },
  { key: "payload", detail: "a mapping" },
  { key: "metadata", detail: "a mapping" },
  { key: "idempotencyKey", detail: "appends once per key" },
] as const;

/** The completions at `pos` in the draft `text`, or null where there are none. `explicit` is a
 *  request (Ctrl+Space): a field name is offered on an empty line only then. */
export function appendCompletionsAt(
  text: string,
  pos: number,
  explicit: boolean,
  known: readonly KnownEventType[],
): CodeEditorCompletions | null {
  const lineStart = text.lastIndexOf("\n", pos - 1) + 1;
  const before = text.slice(lineStart, pos);
  const typeValue = /^(?:\s*-\s+|\s*)type:\s*["']?([\w./@-]*)$/.exec(before);
  if (typeValue)
    return {
      from: pos - typeValue[1]!.length,
      validFor: /^[\w./@-]*$/,
      // CodeMirror sorts equal matches by label; the boost keeps this order (consumed, then by count)
      options: known.map(({ type, detail, section }, index) => ({
        label: type,
        boost: Math.max(-99, 99 - index),
        displayLabel: shortEventType(type),
        detail,
        section,
      })),
    };
  // a field starts a line of the one mapping, or of a list item (`- ` or its two-space continuation)
  const list = /^\s*-/.test(text);
  const field = (list ? /^(?:- | {2})([A-Za-z]*)$/ : /^([A-Za-z]*)$/).exec(before);
  if (!field || (!field[1] && !explicit)) return null;
  const indent = list ? "  " : "";
  // in one mapping, a field already written is not offered again
  const written = list ? new Set<string>() : new Set(text.match(/^[A-Za-z]+(?=:)/gm));
  return {
    from: pos - field[1]!.length,
    validFor: /^[A-Za-z]*$/,
    options: FIELDS.filter(({ key }) => !written.has(key)).map(({ key, detail }) => ({
      label: key,
      detail,
      apply: key === "payload" || key === "metadata" ? `${key}:\n${indent}  ` : `${key}: `,
    })),
  };
}

// The context view's raw composer: YAML (or JSON) for one event or a list of
// them, sent through the caller's `onAppend` with ⌘/Ctrl+Enter or the button. Closed it is one
// "Append event" button under the feed, in the rows' body column, so it never eats the log; open,
// in the same column under one rule, the editor is capped (12rem) and the feed keeps the rest. Typing completes the event's fields and, after `type:`, the types
// this context knows (append-completions.ts); "Examples" loads a draft of a type some processor here
// consumes, grouped by processor. Nothing is inserted here: the appended events arrive by the view's
// live subscription like anyone's, and the view pins the feed to its tail so they land in view. The
// draft stays after a success — the next append is usually a tweak of the last.
import { useMemo, useRef, useState } from "react";
import { PlusIcon, SparklesIcon } from "lucide-react";
import { RowGutter } from "./event-row.tsx";
import { appendCompletionsAt, knownEventTypes } from "./append-completions.ts";
import {
  DEFAULT_APPEND_YAML,
  exampleGroups,
  exampleYaml,
  parseAppendYaml,
  type ContextViewAppendEvent,
} from "./append-events.ts";
import { recount, shortEventType, sortedCounts, type TypeCounts } from "./filters.tsx";
import type { ContextViewEvent, ContextViewProcessor } from "./types.tsx";
import { CodeEditor } from "#/components/code-editor.tsx";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuTrigger,
} from "#/components/ui/dropdown-menu.tsx";
import { Spinner } from "#/components/ui/spinner.tsx";
import { Button } from "#/components/ui/button.tsx";

export function AppendComposer({
  onAppend,
  onAppended,
  events,
  processors,
}: {
  onAppend: (events: ContextViewAppendEvent[]) => Promise<unknown>;
  /** After a success: the view follows its tail to show what lands. */
  onAppended: () => void;
  /** The loaded log: its types are offered as you type one. */
  events: readonly ContextViewEvent[];
  /** The context's processors: what they consume is offered first, and loads as an example. */
  processors: readonly ContextViewProcessor[];
}) {
  const [open, setOpen] = useState(false);
  const [draft, setDraft] = useState(DEFAULT_APPEND_YAML);
  const [pending, setPending] = useState(false);
  /** The last submit's outcome, until the draft changes. */
  const [outcome, setOutcome] = useState<{ error: string } | { appended: number }>();
  const examples = useMemo(() => exampleGroups(processors), [processors]);
  // counted only while open, and then only what the log adds (filters.tsx `recount`)
  const countsRef = useRef<TypeCounts>(undefined);
  const known = useMemo(
    () =>
      open
        ? knownEventTypes(
            sortedCounts((countsRef.current = recount(countsRef.current, events)).counts),
            processors,
          )
        : [],
    [open, events, processors],
  );
  const edit = (value: string) => {
    setDraft(value);
    setOutcome(undefined);
  };
  const blank = draft.trim() === "";
  const submit = async () => {
    if (pending || blank) return;
    const parsed = parseAppendYaml(draft);
    if ("error" in parsed) return setOutcome(parsed);
    setPending(true);
    try {
      await onAppend(parsed.events);
      setOutcome({ appended: parsed.events.length });
      onAppended();
    } catch (error) {
      setOutcome({ error: error instanceof Error ? error.message : String(error) });
    } finally {
      setPending(false);
    }
  };
  if (!open)
    return (
      <div className="flex items-center gap-x-3.5 px-3 sm:px-4 py-1">
        <RowGutter times />
        {/* the button's own padding sits outside the column, so its words line up with the rows' */}
        <Button variant="ghost" size="sm" className="-ml-2" onClick={() => setOpen(true)}>
          <PlusIcon /> Append event
        </Button>
        <span className="hidden text-xs text-muted-foreground sm:inline">YAML · ⌘↵</span>
      </div>
    );
  return (
    <div className="flex gap-x-3.5 border-t px-3 sm:px-4 pt-2 pb-1" data-slot="append-composer">
      <RowGutter times />
      <div className="flex min-w-0 flex-1 flex-col gap-2">
        <CodeEditor
          value={draft}
          onValueChange={edit}
          onSubmit={() => void submit()}
          language="yaml"
          label="Events to append"
          placeholder="type: manual/note-added  (a YAML list appends several)"
          focusOnMount
          complete={(text, pos, explicit) => appendCompletionsAt(text, pos, explicit, known)}
        />
        <div className="flex flex-wrap items-center gap-2">
          {examples.length > 0 ? (
            <DropdownMenu>
              <DropdownMenuTrigger render={<Button variant="ghost" size="sm" />}>
                <SparklesIcon /> Examples
              </DropdownMenuTrigger>
              <DropdownMenuContent align="start" side="top" className="w-auto max-w-80">
                {examples.map((group) => (
                  <DropdownMenuGroup key={group.label}>
                    <DropdownMenuLabel className="truncate">{group.label}</DropdownMenuLabel>
                    {group.types.map((type) => (
                      <DropdownMenuItem
                        key={type}
                        title={type}
                        onClick={() => edit(exampleYaml(type))}
                        className="font-mono text-xs"
                      >
                        <span className="truncate">{shortEventType(type)}</span>
                      </DropdownMenuItem>
                    ))}
                  </DropdownMenuGroup>
                ))}
              </DropdownMenuContent>
            </DropdownMenu>
          ) : null}
          <span className="min-w-0 flex-1 truncate text-xs" role="status">
            {outcome && "error" in outcome ? (
              <span data-type="error" className="text-destructive" title={outcome.error}>
                {outcome.error}
              </span>
            ) : outcome ? (
              <span className="text-muted-foreground">
                Appended {outcome.appended === 1 ? "1 event" : `${String(outcome.appended)} events`}
              </span>
            ) : (
              <span className="hidden text-muted-foreground sm:inline">
                YAML or JSON · Tab completes · ⌘↵ appends
              </span>
            )}
          </span>
          <Button variant="ghost" size="sm" onClick={() => setOpen(false)}>
            Close
          </Button>
          <Button
            size="sm"
            onClick={() => void submit()}
            disabled={pending || blank}
            title="Append events (⌘↵)"
          >
            {pending ? <Spinner /> : null} Append
          </Button>
        </div>
      </div>
    </div>
  );
}

// The append composer's YAML, read as events: one event (a mapping) or a list of them, each checked
// only as far as `append` itself checks (a non-empty string `type`) plus the envelope's shape — an
// object `payload`/`metadata`, a string `idempotencyKey`, no other field. Anything else is the
// platform's to accept or refuse. Pure: the composer (append-composer.tsx) shows the error string.
import { parse, stringify } from "yaml";

/** What the composer hands `onAppend`: the part of an event a person may write. */
export type ContextViewAppendEvent = {
  type: string;
  payload?: Record<string, unknown>;
  metadata?: Record<string, unknown>;
  idempotencyKey?: string;
};

/** A prefilled draft: a type opaque to the platform (no `events.iterate.com/` prefix — see
 *  core/lib/README.md#event-types), so a stray append never reads as one of its facts. */
export const DEFAULT_APPEND_YAML = "type: manual/note-added\npayload:\n  text: Hello\n";

const FIELDS = new Set(["type", "payload", "metadata", "idempotencyKey"]);

/** The events the YAML names, or why it names none. An empty draft is an error too: nothing to send. */
export function parseAppendYaml(
  text: string,
): { events: ContextViewAppendEvent[] } | { error: string } {
  let parsed: unknown;
  try {
    parsed = parse(text);
  } catch (error) {
    return { error: `Not YAML: ${error instanceof Error ? error.message : String(error)}` };
  }
  if (parsed == null) return { error: "Nothing to append." };
  const list = Array.isArray(parsed) ? parsed : [parsed];
  if (list.length === 0) return { error: "Nothing to append." };
  const events: ContextViewAppendEvent[] = [];
  for (const [index, entry] of list.entries()) {
    const where = Array.isArray(parsed) ? `Event ${String(index + 1)}: ` : "";
    if (!isObject(entry)) return { error: `${where}an event is a mapping with a \`type\`.` };
    const unknown = Object.keys(entry).find((key) => !FIELDS.has(key));
    if (unknown) return { error: `${where}unknown field \`${unknown}\`.` };
    const { type, payload, metadata, idempotencyKey } = entry;
    if (typeof type !== "string" || type.trim() === "")
      return { error: `${where}\`type\` must be a non-empty string.` };
    if (payload !== undefined && !isObject(payload))
      return { error: `${where}\`payload\` must be a mapping.` };
    if (metadata !== undefined && !isObject(metadata))
      return { error: `${where}\`metadata\` must be a mapping.` };
    if (idempotencyKey !== undefined && typeof idempotencyKey !== "string")
      return { error: `${where}\`idempotencyKey\` must be a string.` };
    events.push({ type, payload, metadata, idempotencyKey });
  }
  return { events };
}

/** A draft for one type, as the examples load it. */
export function exampleYaml(type: string): string {
  return stringify({ type, payload: {} });
}

/** The examples a person can load, grouped by the processors that consume them (one group per
 *  processor): what some processor here reacts to. Processors that
 *  consume the same types share one group (a tab's live-state subscribers are many and alike), named
 *  by the first and how many more; a type shows once, in its first group. Wildcards (`*`, `…/*`)
 *  name no one type and are left out; a group with no type left is dropped. */
export function exampleGroups(
  processors: readonly { name: string; consumes?: readonly string[] }[],
): { label: string; types: string[] }[] {
  const byTypes = new Map<string, { names: string[]; types: string[] }>();
  for (const processor of [...processors].sort((a, b) => a.name.localeCompare(b.name))) {
    const types = [...new Set(processor.consumes || [])]
      .filter((type) => !type.includes("*"))
      .sort();
    const key = types.join("\n");
    const group = byTypes.get(key) || { names: [], types };
    group.names.push(processor.name);
    byTypes.set(key, group);
  }
  const shown = new Set<string>();
  const groups: { label: string; types: string[] }[] = [];
  for (const { names, types } of byTypes.values()) {
    const fresh = types.filter((type) => !shown.has(type));
    for (const type of fresh) shown.add(type);
    if (fresh.length === 0) continue;
    const label = names.length > 1 ? `${names[0]!} +${String(names.length - 1)}` : names[0]!;
    groups.push({ label, types: fresh });
  }
  return groups;
}

function isObject(value: unknown): value is Record<string, unknown> {
  return Boolean(value) && typeof value === "object" && !Array.isArray(value);
}

// A context's path, once, each segment a link up: `/ repos / config`, the last segment the page's
// own. The link target is the caller's (`ContextPathLinks`): the UI kit knows no routes, so an app
// says what URL a path opens and, with a client router, takes the plain click itself — the way
// AppShell's `projectHref` and `onNavigate` work.
import { createContext, useContext, type ReactNode, type SyntheticEvent } from "react";
import { cn } from "cn";
import { plainLeftClick } from "#/lib/plain-left-click.ts";

/** Where a context path links to, the app's: `hrefOf("/repos")` is its URL; `onNavigate`, when the
 *  app has a client router, takes a plain click or an Enter (it prevents the default and navigates).
 *  Without it a link is a page load. */
export type ContextPathLinks = {
  hrefOf: (path: string) => string;
  onNavigate?: (href: string, event: SyntheticEvent) => void;
};

/** The links a context view's rows use for the paths they name (a child context's): provided by
 *  `ContextView` from its `pathLinks`, absent where the app gave none. */
export const ContextPathLinksContext = createContext<ContextPathLinks | undefined>(undefined);

/** Go to `path` as the app does it: its router, else a page load. */
export function navigateToPath(links: ContextPathLinks, path: string, event: SyntheticEvent) {
  const href = links.hrefOf(path);
  if (links.onNavigate) links.onNavigate(href, event);
  else window.location.assign(href);
}

/** An anchor to a context path: a plain click goes through the app's router, a modified or middle
 *  click is the browser's. */
export function PathLink({
  path,
  links,
  className,
  children,
  ...rest
}: {
  path: string;
  links: ContextPathLinks;
  className?: string;
  children: ReactNode;
  "aria-current"?: "page";
  "aria-label"?: string;
}) {
  const href = links.hrefOf(path);
  return (
    <a
      href={href}
      className={className}
      onClick={(event) => {
        // a link inside an inspectable row opens the path, not the inspector
        event.stopPropagation();
        if (links.onNavigate && plainLeftClick(event)) links.onNavigate(href, event);
      }}
      {...rest}
    >
      {children}
    </a>
  );
}

/** A path a row names (`Child context /repos/config created`): a link when the view has
 *  `pathLinks`, else the path as text. The path is the children too, so a sentence's text (the
 *  fold's fact, folds.tsx `sentenceText`) still carries it. */
export function ContextPathText({ path }: { path: string }) {
  const links = useContext(ContextPathLinksContext);
  if (!links) return <span className="font-mono">{path}</span>;
  return (
    <PathLink
      path={path}
      links={links}
      className="font-mono underline decoration-border underline-offset-2 hover:decoration-foreground"
    >
      {path}
    </PathLink>
  );
}

/** `/ repos / config`: the root and each segment up a muted link, the last segment the page's. */
export function ContextPath({
  path,
  links,
  className,
}: {
  path: string;
  links: ContextPathLinks;
  className?: string;
}) {
  const segments = path.split("/").filter(Boolean);
  const up = "text-muted-foreground hover:text-foreground";
  return (
    <nav
      aria-label="Context path"
      className={cn("flex min-w-0 items-baseline gap-1 font-mono text-sm", className)}
    >
      {segments.length === 0 ? (
        <span aria-current="page" className="font-semibold">
          /
        </span>
      ) : (
        <PathLink path="/" links={links} className={up} aria-label="/">
          /
        </PathLink>
      )}
      {segments.map((segment, index) => {
        const last = index === segments.length - 1;
        const to = `/${segments.slice(0, index + 1).join("/")}`;
        return (
          <span key={to} className="flex min-w-0 items-baseline gap-1">
            {index ? <span className="text-muted-foreground">/</span> : null}
            {last ? (
              <span aria-current="page" className="truncate font-semibold">
                {segment}
              </span>
            ) : (
              <PathLink path={to} links={links} className={up}>
                {segment}
              </PathLink>
            )}
          </span>
        );
      })}
    </nav>
  );
}

// The context tree: every context an app knows (a project's registry, the global namespace's
// announced children) as an indented tree, `/` first, the one shown marked — the explorer's
// navigation. One input over it, "Filter or go to a path": typing
// narrows the tree to the paths that contain it; Enter opens the one match, else the path typed,
// resolved against the one shown by the caller's `resolvePath` (the SDK's `resolveContextPath`, so
// `..` and `/agents/x` work); "/" anywhere on the page focuses it. A segment no context sits at
// (`/agents` over `/agents/web`) is a heading, not a link. Pure: the paths, the current one and
// where a path links (`ContextPathLinks`) are props.
//
// `ContextTree` is the pane (a wide screen's left column); `ContextTreeSheet` is a phone's: the path
// as a button that opens the same tree in a left Sheet.
import { useEffect, useMemo, useRef, useState } from "react";
import { ChevronDownIcon } from "lucide-react";
import { cn } from "cn";
import { navigateToPath, PathLink, type ContextPathLinks } from "./context-path.tsx";
import { Input } from "#/components/ui/input.tsx";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from "#/components/ui/sheet.tsx";

type TreeRow = { path: string; name: string; depth: number; context: boolean };

/** The paths as tree rows, depth first in segment order; every ancestor a row, `/` the first. */
export function contextTreeRows(paths: readonly string[]): TreeRow[] {
  const known = new Set(["/", ...paths]);
  const all = new Set<string>(["/"]);
  for (const path of known) {
    const segments = path.split("/").filter(Boolean);
    for (let at = 1; at <= segments.length; at++) all.add(`/${segments.slice(0, at).join("/")}`);
  }
  return [...all]
    .map((path) => path.split("/").filter(Boolean))
    .sort((a, b) => {
      for (let at = 0; at < Math.min(a.length, b.length); at++)
        if (a[at] !== b[at]) return a[at]! < b[at]! ? -1 : 1;
      return a.length - b.length;
    })
    .map((segments) => {
      const path = `/${segments.join("/")}`;
      return {
        path,
        name: segments.at(-1) ?? "/",
        depth: segments.length,
        context: known.has(path),
      };
    });
}

export function ContextTree({
  paths,
  current,
  links,
  resolvePath,
  className,
}: {
  /** Every context path known; `/` is always listed. */
  paths: readonly string[];
  /** The path shown. */
  current: string;
  links: ContextPathLinks;
  /** A typed path, resolved against the one shown (`resolveContextPath(current, typed)`). */
  resolvePath: (typed: string) => string;
  className?: string;
}) {
  const [query, setQuery] = useState("");
  const inputRef = useRef<HTMLInputElement>(null);
  const rows = useMemo(() => contextTreeRows(paths), [paths]);
  const total = rows.filter((row) => row.context).length;
  const needle = query.trim();
  // filtered, the matches read flat, as whole paths
  const matches = needle
    ? rows.filter((row) => row.context && row.path.includes(needle))
    : undefined;
  // "/" focuses the input from anywhere but a field of the page's own
  useEffect(() => {
    const onKey = (event: KeyboardEvent) => {
      if (event.key !== "/" || event.metaKey || event.ctrlKey || event.altKey) return;
      const target = event.target;
      if (
        target instanceof HTMLElement &&
        (target.isContentEditable || target.closest("input, textarea, select, [role=textbox]"))
      )
        return;
      const input = inputRef.current;
      if (!input?.offsetParent) return; // hidden (the other breakpoint's tree)
      event.preventDefault();
      input.focus();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);
  const row = "flex h-[26px] min-w-0 items-center rounded-md pr-2 whitespace-nowrap";
  return (
    <nav aria-label="Contexts" className={cn("flex min-h-0 flex-col gap-1.5", className)}>
      <form
        className="relative"
        onSubmit={(event) => {
          event.preventDefault();
          if (!needle) return;
          const only = matches?.length === 1 ? matches[0]!.path : undefined;
          setQuery("");
          navigateToPath(links, only || resolvePath(needle), event);
        }}
      >
        <Input
          ref={inputRef}
          aria-label="Filter or go to a path"
          placeholder="Filter or go to a path"
          className="h-8 pr-9 font-mono text-xs md:text-xs"
          value={query}
          onChange={(event) => setQuery(event.target.value)}
          onKeyDown={(event) => {
            if (event.key === "Escape") setQuery("");
          }}
        />
        <kbd className="pointer-events-none absolute top-1/2 right-2 -translate-y-1/2 rounded border px-1 font-sans text-[10px] text-muted-foreground">
          {needle ? "↵ go" : "/"}
        </kbd>
      </form>
      <ul className="min-h-0 flex-1 overflow-y-auto font-mono text-[13px]">
        {(matches || rows).map((item) => {
          const indent = { paddingLeft: `${String(8 + (matches ? 0 : item.depth) * 12)}px` };
          const label = matches ? item.path : item.name;
          return (
            <li key={item.path}>
              {item.context ? (
                <PathLink
                  path={item.path}
                  links={links}
                  aria-label={item.path}
                  aria-current={item.path === current ? "page" : undefined}
                  className={cn(
                    row,
                    "text-foreground/85 hover:bg-muted/60 aria-[current=page]:bg-muted aria-[current=page]:font-semibold aria-[current=page]:text-foreground",
                  )}
                >
                  <span style={indent} className="truncate">
                    {label}
                  </span>
                </PathLink>
              ) : (
                <span className={cn(row, "text-muted-foreground")}>
                  <span style={indent} className="truncate">
                    {label}
                  </span>
                </span>
              )}
            </li>
          );
        })}
      </ul>
      <p className="px-2 text-[11px] text-muted-foreground">
        {matches
          ? `${String(matches.length)} of ${String(total)} contexts`
          : total > 1
            ? `${String(total)} contexts`
            : "Contexts show up here as they're created."}
      </p>
    </nav>
  );
}

/** A phone's tree: the path shown, as a button, opening the tree in a left Sheet that closes as a
 *  path is picked. */
export function ContextTreeSheet({ className, ...tree }: Parameters<typeof ContextTree>[0]) {
  const [open, setOpen] = useState(false);
  const links = useMemo(
    (): ContextPathLinks => ({
      hrefOf: tree.links.hrefOf,
      onNavigate: (href, event) => {
        setOpen(false);
        if (tree.links.onNavigate) tree.links.onNavigate(href, event);
        else window.location.assign(href);
      },
    }),
    [tree.links],
  );
  return (
    <Sheet open={open} onOpenChange={setOpen}>
      <SheetTrigger
        className={cn(
          "flex min-w-0 items-center gap-1 rounded-md bg-muted px-2 py-0.5 font-mono text-sm",
          className,
        )}
        aria-label={`Contexts: ${tree.current}`}
      >
        <span className="truncate">{tree.current}</span>
        <ChevronDownIcon className="size-3.5 shrink-0 text-muted-foreground" />
      </SheetTrigger>
      <SheetContent side="left" className="gap-2 p-3">
        <SheetHeader className="p-1">
          <SheetTitle>Contexts</SheetTitle>
        </SheetHeader>
        <ContextTree {...tree} links={links} className="flex-1" />
      </SheetContent>
    </Sheet>
  );
}

// The context view's state as a URL's search — every choice a person makes in the view that they
// would share or come back to: the mode, the filter (query, types, actor, offset range), the
// inspected event, the processors sheet, the filter row. zod only, router-agnostic: an app's route hands the parsed
// search in as `state` and applies `onStateChange` patches with its router (`validateSearch:
// ContextViewState`, `navigate({ search: (prev) => ({ ...prev, ...patch }), replace: true })`).
// Every key `.catch(undefined)`: a hand-edited `?event=abc` is an absent key, never an error page.
import { z } from "zod";
import type { ContextViewFilter } from "./filters.tsx";

export const ContextViewState = z.object({
  /** How the log reads; omitted = the app's default (Pretty). */
  mode: z.enum(["pretty", "pretty-raw", "raw"]).optional().catch(undefined),
  /** The text query over the type and the payload. */
  q: z.string().optional().catch(undefined),
  /** The event types left ticked; omitted = all. */
  types: z.array(z.string()).optional().catch(undefined),
  /** One actor's events only. */
  actor: z.string().optional().catch(undefined),
  /** The lowest offset shown, inclusive. */
  from: z.number().int().nonnegative().optional().catch(undefined),
  /** The highest offset shown, inclusive. */
  to: z.number().int().nonnegative().optional().catch(undefined),
  /** The inspected event's offset — the inspector is open. */
  event: z.number().int().nonnegative().optional().catch(undefined),
  /** The processors sheet is open. */
  processors: z.literal(true).optional().catch(undefined),
  /** The filter row is open. */
  filter: z.literal(true).optional().catch(undefined),
});

/** The view's state — what `ContextView` reads and patches; a URL's search in every app. */
export type ContextViewState = z.infer<typeof ContextViewState>;

/** The filter the rows are narrowed by, from the state's filter keys. */
export function contextViewFilterOf(state: ContextViewState): ContextViewFilter {
  return {
    query: state.q || "",
    types: new Set(state.types || []),
    actor: state.actor,
    from: state.from,
    to: state.to,
  };
}

/** The patch that drops every filter key (the filter row's "clear"). */
export const FILTER_CLEARED = {
  q: undefined,
  types: undefined,
  actor: undefined,
  from: undefined,
  to: undefined,
} satisfies Partial<ContextViewState>;

/** The keys that claim the view's right edge — an opener clears the others so one sheet shows. */
export const RIGHT_EDGE_CLOSED = {
  event: undefined,
  processors: undefined,
} satisfies Partial<ContextViewState>;

// THE CONTEXT VIEW — one context's stream with its processors and its presence, the general-purpose
// view every app reuses (the dash's activity pages, the agents feed's base): a strip, one line (what
// this is — a path once, each segment a link up, `context-path.tsx` —, how many events, who is here,
// then Pretty | Raw, Filter and Processors as labelled text buttons), a filter row (a text query, the types
// left ticked), the log folded for reading (folds.tsx) as rows one line wide on a desktop and two
// on a phone, and two right-edge sheets — the inspector for one event, the processors with their
// live state. Two modes on the strip: Pretty (sentences, housekeeping folded, repeats counted) and
// Raw (the log as data); Pretty + raw (every event, sentence and raw line) is still a URL's
// `mode=pretty-raw`, and what an opened fold lists. Nothing here ever
// scrolls sideways; the inspector shows what a line cuts.
// BUILT FOR 100,000 EVENTS: the log arrives newest page first and grows at both ends (live
// appends, older pages as the reader scrolls up — `older`); the filter, the type counts and the fold
// follow that growth instead of passing over the whole log again (folds.tsx `refold`), and the rows
// are one virtual list in the view's own scroll region (feed-list.tsx), so the view needs a bounded
// height from its caller (a flex child that fills the page).
// CONTROLLED: every choice a person makes here is `state` (context-view-search.ts — a URL's search
// in every app) and comes back as an `onStateChange` patch, so a view is a link: the mode, the
// filter, the inspected event, the open sheet. Only the folds opened in place stay local — scroll-
// position-grade ephemera. Pure otherwise: the context arrives as ONE prop, `context` — what the
// SDK's `useIterateContext(itx)` returns, typed structurally here (`ContextViewSource`) so the UI kit
// stays free of the SDK: `<ContextView context={useIterateContext(itx)} … />`.
// APPENDING: given `onAppend` (the caller's `itx.append`), a raw YAML composer sits under the feed
// (append-composer.tsx), closed to one button; what it appends arrives by the live subscription, and
// the feed follows its tail so it lands in view. No `onAppend`, no composer.
import { useCallback, useMemo, useRef, useState, type CSSProperties, type ReactNode } from "react";
import { cn } from "cn";
import { ContextPathLinksContext, type ContextPathLinks } from "./context-path.tsx";
import {
  contextViewFilterOf,
  RIGHT_EDGE_CLOSED,
  type ContextViewState,
} from "./context-view-search.ts";
import { coreEventInspectors, coreEventRenderers } from "./core-renderers.tsx";
import { EventInspector } from "./event-inspector.tsx";
import { FeedList } from "./feed-list.tsx";
import {
  actorLabel,
  narrows,
  recount,
  refilter,
  sortedCounts,
  type Filtered,
  type TypeCounts,
} from "./filters.tsx";
import { refold, sentenceText, type Fold } from "./folds.tsx";
import { AppendComposer } from "./append-composer.tsx";
import { type ContextViewAppendEvent } from "./append-events.ts";
import { FilterRow } from "./filter-row.tsx";
import { EventRate, PresenceStrip } from "./presence-strip.tsx";
import { ProcessorsPanel } from "./processors-panel.tsx";
import {
  type ContextViewEvent,
  type ContextViewMode,
  type ContextViewPresence,
  type ContextViewProcessor,
  type LiveStateView,
  type EventInspectors,
  type EventRenderers,
  rendererFor,
} from "./types.tsx";
import { Spinner } from "#/components/ui/spinner.tsx";

const MODES: { id: ContextViewMode; label: string }[] = [
  { id: "pretty", label: "Pretty" },
  { id: "raw", label: "Raw" },
];

/** The strip's text buttons: a word, muted, the one that is on on a quiet fill — no border. */
const stripButton = (on: boolean) =>
  cn(
    "rounded-md px-2 py-0.5 whitespace-nowrap",
    on ? "bg-muted text-foreground" : "text-muted-foreground hover:text-foreground",
  );

export function ContextView({
  title,
  context,
  error: callerError,
  renderers,
  inspectors,
  state,
  onStateChange,
  onAppend,
  pathLinks,
  emptyText = "Nothing has happened on this context yet.",
  className,
}: {
  /** What this context is, for the strip: a path (`ContextPath`), a name. */
  title: ReactNode;
  /** The context, live: what `useIterateContext(itx)` returns. */
  context: ContextViewSource;
  /** The caller's own failure (opening the context), shown over the context's. */
  error?: string;
  renderers?: EventRenderers;
  /** Rich inspector bodies by type — over the platform's own (a script's code, its result). */
  inspectors?: EventInspectors;
  /** The view's state — the route's parsed search (`validateSearch: ContextViewState`). */
  state: ContextViewState;
  /** A patch to the state; an `undefined` value drops the key (the route spreads it into the search). */
  onStateChange: (patch: Partial<ContextViewState>) => void;
  /** Append to the context (`(events) => itx.append(...events)`); omitted = a view with no composer.
   *  The platform stamps who appended: nothing to add here. */
  onAppend?: (events: ContextViewAppendEvent[]) => Promise<unknown>;
  /** Where a context path a row names links (a child context's); omitted = plain text. */
  pathLinks?: ContextPathLinks;
  emptyText?: string;
  className?: string;
}) {
  const { events, caughtUp, older = OLDER_EXHAUSTED, head, presence, liveState } = context;
  const processors = context.processors.rows;
  const error = callerError || context.error || context.processors.error;
  const mode = state.mode || "pretty";
  const filter = useMemo(() => contextViewFilterOf(state), [state]);
  const filtering = Boolean(state.filter);
  const inspected = state.event;
  /** The folds opened in place, by item key. */
  const [opened, setOpened] = useState<ReadonlySet<string>>(() => new Set());
  /** Bumped by each append from here: the feed goes back to its tail to show it land. */
  const [followTail, setFollowTail] = useState(0);
  // the platform's own events read as sentences everywhere; an app's renderers lie over them
  const allRenderers = useMemo(() => ({ ...coreEventRenderers, ...renderers }), [renderers]);
  const allInspectors = useMemo(() => ({ ...coreEventInspectors, ...inspectors }), [inspectors]);
  // Each pass below keeps what it made last (a ref) and redoes only what the log's growth changed:
  // the added events filtered, the fold's seam re-folded, the added types counted.
  const filteredRef = useRef<Filtered>(undefined);
  const shown = useMemo(
    () => (filteredRef.current = refilter(filteredRef.current, events, filter)).shown,
    [events, filter],
  );
  // the same fact = the same sentence: four sign-ins fold whatever their timestamps and ids say.
  // Remembered per event: a fold asks it of every event it passes, and a render per ask is most of
  // a fold's time.
  const factOf = useMemo(() => {
    const facts = new WeakMap<ContextViewEvent, string>();
    return (event: ContextViewEvent) => {
      let fact = facts.get(event);
      if (!fact) {
        const sentence = rendererFor(allRenderers, event.type)?.(event);
        const text = sentence ? sentenceText(sentence) : "";
        fact = `${event.type}\u0000${text || JSON.stringify(event.payload ?? null)}`;
        facts.set(event, fact);
      }
      return fact;
    };
  }, [allRenderers]);
  const foldRef = useRef<Fold>(undefined);
  const { items, namedBefore } = useMemo(
    () => (foldRef.current = refold(foldRef.current, shown, mode, factOf, actorLabel)),
    [shown, mode, factOf],
  );
  // counted only while the filter row that lists them is open
  const countsRef = useRef<TypeCounts>(undefined);
  const types = useMemo(
    () =>
      filtering
        ? sortedCounts((countsRef.current = recount(countsRef.current, events)).counts)
        : [],
    [events, filtering],
  );
  const filtered = narrows(filter);
  // stable, so the memoised rows skip the re-render every scroll frame and every append brings
  const toggleOpened = useCallback(
    (key: string) =>
      setOpened((held) => {
        const next = new Set(held);
        if (!next.delete(key)) next.add(key);
        return next;
      }),
    [],
  );
  const onStateChangeRef = useRef(onStateChange);
  onStateChangeRef.current = onStateChange;
  const inspect = useCallback(
    (offset: number) => onStateChangeRef.current({ ...RIGHT_EDGE_CLOSED, event: offset }),
    [],
  );
  const loaded = events.length.toLocaleString();
  const count = filtered
    ? `${shown.length.toLocaleString()} of ${loaded} loaded events`
    : older.exhausted
      ? `${loaded} events`
      : `${loaded} loaded of ~${(head ?? 0).toLocaleString()} events`;
  // every row's columns start in line: the offset gutter fits the largest offset, `#` included
  // (the feed's rows, the day marks and the composer read it); cast: React's CSSProperties has no
  // index for a custom property
  const gutter = {
    "--offset-width": `${String(String(events.at(-1)?.offset ?? 0).length + 1)}ch`,
  } as CSSProperties;
  return (
    <div className={cn("flex min-h-0 min-w-0 flex-col", className)} style={gutter}>
      <div className="flex flex-wrap items-center gap-x-4 gap-y-1 px-3 sm:px-4 py-1.5">
        <div className="flex min-w-0 items-baseline gap-4">
          <div className="min-w-0 truncate text-sm">{title}</div>
          <span className="shrink-0 text-xs text-muted-foreground tabular-nums">
            {count}
            {caughtUp ? "" : " · loading"}
            <EventRate events={events} />
          </span>
        </div>
        <PresenceStrip
          className="hidden min-w-0 xl:flex"
          actors={presence.actors}
          rpcStubs={presence.rpcStubs}
          onPick={(actor) => onStateChange({ actor: filter.actor === actor ? undefined : actor })}
        />
        <div className="ml-auto flex items-center gap-3 text-xs">
          <div role="tablist" aria-label="How the log reads" className="flex gap-0.5">
            {MODES.map((candidate) => (
              <button
                key={candidate.id}
                type="button"
                role="tab"
                aria-selected={mode === candidate.id}
                onClick={() =>
                  onStateChange({ mode: candidate.id === "pretty" ? undefined : candidate.id })
                }
                className={stripButton(mode === candidate.id)}
              >
                {candidate.label}
              </button>
            ))}
          </div>
          <button
            type="button"
            onClick={() => onStateChange({ filter: filtering ? undefined : true })}
            aria-expanded={filtering}
            className={stripButton(filtering || filtered)}
          >
            Filter
          </button>
          <button
            type="button"
            onClick={() => onStateChange({ ...RIGHT_EDGE_CLOSED, processors: true })}
            className={stripButton(false)}
          >
            Processors <span className="text-foreground tabular-nums">{processors.length}</span>
          </button>
        </div>
      </div>
      {filtering ? (
        <div className="px-3 sm:px-4 pb-2">
          <FilterRow
            filter={filter}
            counts={types}
            narrowed={filtered}
            partial={!older.exhausted}
            loaded={loaded}
            onStateChange={onStateChange}
          />
        </div>
      ) : null}
      {error ? (
        <p data-type="error" className="px-3 sm:px-4 text-sm text-destructive">
          {error}
        </p>
      ) : null}
      <ContextPathLinksContext value={pathLinks}>
        <FeedList
          items={items}
          namedBefore={namedBefore}
          mode={mode}
          renderers={allRenderers}
          inspected={inspected}
          onInspect={inspect}
          opened={opened}
          onToggle={toggleOpened}
          older={older}
          followTail={followTail}
          empty={
            error ? null : caughtUp ? (
              <p className="px-3 sm:px-4 py-6 text-sm text-muted-foreground">
                {filtered ? "No event matches the filter." : emptyText}
              </p>
            ) : (
              <div className="flex items-center gap-2 px-3 sm:px-4 py-6 text-sm text-muted-foreground">
                <Spinner /> Loading the log…
              </div>
            )
          }
        />
      </ContextPathLinksContext>
      {onAppend ? (
        <AppendComposer
          onAppend={onAppend}
          onAppended={() => setFollowTail((count) => count + 1)}
          events={events}
          processors={processors}
        />
      ) : null}
      <EventInspector
        events={events}
        offset={inspected}
        older={older}
        renderers={allRenderers}
        inspectors={allInspectors}
        onNavigate={inspect}
        onClose={() => onStateChange({ event: undefined })}
      />
      <ProcessorsPanel
        open={Boolean(state.processors)}
        onClose={() => onStateChange({ processors: undefined })}
        processors={processors}
        presence={presence}
        liveState={liveState}
        events={events}
        head={head}
        onPickActor={(actor) => onStateChange({ actor, processors: undefined })}
      />
    </div>
  );
}

/** What `ContextView` reads of the SDK's `useIterateContext` result — structural, so any source of
 *  the same shape renders (a test's fixture, a recorded log). */
export type ContextViewSource = {
  /** The events loaded, sorted by offset. */
  events: readonly ContextViewEvent[];
  caughtUp: boolean;
  error?: string;
  /** Reading the log below what is loaded; omitted = the whole log is loaded. */
  older?: { loadOlder(): void; loading: boolean; exhausted: boolean };
  /** The newest offset of the log, so the strip can say how much of it is loaded. */
  head?: number;
  /** The subscriptions table (`itx.subscriptions.list()`): a row hosting a facet is a processor. */
  processors: { rows: readonly ContextViewProcessor[]; error?: string };
  presence: { actors: readonly ContextViewPresence[]; rpcStubs: readonly string[] };
  /** Each live state by name — `core`, and every hosted facet's — for the processors panel. */
  liveState: Record<string, LiveStateView>;
};

/** The whole log is loaded: nothing older to read. */
const OLDER_EXHAUSTED = { loadOlder: () => {}, loading: false, exhausted: true };

// The platform's own events, as sentences — what every context's log carries whatever the app:
// the stream's lifecycle, its subscriptions, live state, the context's script runs. The view lays
// an app's renderers over these (the app's win), so a page never shows `itx/woken {"incarnation"…}`.
import { ContextPathText } from "./context-path.tsx";
import { mono, record, str } from "./renderer-helpers.tsx";
import type { EventInspectors, EventRenderers } from "./types.tsx";

/** The platform's housekeeping reads quieter than what people and apps did. */
const quiet = (text: string) => <span className="text-muted-foreground">{text}</span>;

/** The platform's HOUSEKEEPING — what the stream does to keep itself running (waking, wiring a
 *  client's subscription, a live-state tick, a scheduled append), never what anyone did. Pretty mode
 *  folds a run of these into one quiet row; the birth, a pause and a script run are not housekeeping. */
export function isHousekeeping(type: string): boolean {
  return (
    type === "events.iterate.com/itx/woken" ||
    type.startsWith("events.iterate.com/itx/subscription-") ||
    type.startsWith("events.iterate.com/itx/schedule-") ||
    type === "events.iterate.com/itx/live-state-changed"
  );
}

/** One line for a folded run of housekeeping: `woke, subscription ×8, live state` — a kind once,
 *  its count only when it repeats. */
export function housekeepingSummary(types: readonly string[]): string {
  const counts = new Map<string, number>();
  for (const type of types) {
    const label =
      type === "events.iterate.com/itx/woken"
        ? "woke"
        : type.startsWith("events.iterate.com/itx/subscription-")
          ? "subscription"
          : type === "events.iterate.com/itx/live-state-changed"
            ? "live state"
            : "scheduled append";
    counts.set(label, (counts.get(label) || 0) + 1);
  }
  return [...counts.entries()]
    .map(([label, n]) => (n > 1 ? `${label} ×${String(n)}` : label))
    .join(", ");
}

/** The inspector's rich bodies for the platform's events: a script run's code, its result. */
export const coreEventInspectors: EventInspectors = {
  "events.iterate.com/itx/run-requested": (e) => (
    <pre className="overflow-x-auto rounded-md bg-muted p-3 font-mono text-xs whitespace-pre-wrap break-words">
      {str(record(e.payload).code)}
    </pre>
  ),
  "events.iterate.com/itx/run-settled": (e) => {
    const s = record(record(e.payload).settlement);
    return s.status === "succeeded" ? (
      <pre className="overflow-x-auto rounded-md bg-muted p-3 font-mono text-xs whitespace-pre-wrap break-words">
        {JSON.stringify(s.result ?? null, null, 2)}
      </pre>
    ) : (
      <p data-type="error" className="text-sm text-destructive">
        {str(s.failureKind)}: {str(s.error)}
      </p>
    );
  },
};

export const coreEventRenderers: EventRenderers = {
  "events.iterate.com/itx/created": () => quiet("The context was born"),
  "events.iterate.com/itx/woken": (e) => {
    const p = record(e.payload);
    // what began the chain that woke it: `<ISO> with <origin> ~<nonce>` (core/os/src/cause.ts)
    const began = e.source?.cause?.chain.match(/ with (.*) ~[a-z0-9]+$/)?.[1];
    // the context's Durable Object started again (an eviction, a deploy): purple
    return (
      <span className="text-purple-700">
        Woke · {str(p.cause, "?")}
        {typeof p.call === "string" ? <> {mono(p.call)}</> : ""}
        {Array.isArray(p.due) && p.due.length > 0 ? ` (${p.due.map(String).join(", ")})` : ""}
        {typeof p.caller === "string" ? ` (${p.caller})` : ""} · incarnation {String(p.incarnation)}
        {began ? ` · began with ${began}` : ""}
      </span>
    );
  },
  "events.iterate.com/itx/paused": (e) => quiet(`Paused ${str(record(e.payload).reason)}`),
  "events.iterate.com/itx/resumed": () => quiet("Resumed"),
  "events.iterate.com/itx/child-created": (e) => (
    <span className="text-muted-foreground">
      Child context <ContextPathText path={str(record(e.payload).childPath)} /> created
    </span>
  ),
  "events.iterate.com/itx/subscription-configured": (e) => {
    const p = record(e.payload);
    const consumes = Array.isArray(p.consumes) ? p.consumes.map(String) : [];
    return (
      <span className="text-muted-foreground">
        Subscription {mono(str(p.name))} configured
        {consumes.length > 0 ? <> · consumes {mono(consumes.join(", "))}</> : null}
      </span>
    );
  },
  "events.iterate.com/itx/live-state-changed": () => quiet("Live state changed"),
  "events.iterate.com/itx/run-requested": (e) => {
    const code = str(record(e.payload).code);
    return <>Ran a script {mono((code.split("\n")[0] || "").slice(0, 100))}</>;
  },
  "events.iterate.com/itx/run-settled": (e) => {
    const p = record(e.payload);
    const s = record(p.settlement);
    return s.status === "succeeded" ? (
      <>
        Script {mono(`#${String(p.requestOffset)}`)} returned{" "}
        {mono(JSON.stringify(s.result ?? null).slice(0, 100))}
      </>
    ) : (
      <>
        Script {mono(`#${String(p.requestOffset)}`)} failed ({str(s.failureKind)}):{" "}
        {str(s.error).slice(0, 140)}
      </>
    );
  },
};

// The inspector's pure halves: where the inspected offset sits in the loaded
// log (the event, its neighbours — by comparison, not offset ± 1, since a log's offsets are sparse
// where ephemeral events were and a stale link still finds real neighbours), the gap to each, the
// signal-first key order the raw event reads in, and which keydowns ← → must leave alone.
import { formatDelta } from "./event-row.tsx";
import type { ContextViewEvent } from "./types.tsx";

/** The inspected offset in a log sorted by offset: the event (when loaded), the events either side
 *  of the offset (whether or not it is loaded) and where it falls against what is held. */
export type InspectedPlace = {
  event?: ContextViewEvent;
  previous?: ContextViewEvent;
  next?: ContextViewEvent;
  /** `below` — older than every loaded event (a page to read); `above` — newer than the head held
   *  (it may yet arrive); `gap` — inside the loaded range, but no event has it. */
  missing?: "below" | "above" | "gap";
};

/** Where `offset` sits in `events` (sorted by offset): one binary search, the log can be 100,000
 *  long. */
export function inspectedPlace(
  events: readonly ContextViewEvent[],
  offset: number,
): InspectedPlace {
  // the first index whose offset is >= the inspected one
  let low = 0;
  let high = events.length;
  while (low < high) {
    const middle = (low + high) >> 1;
    if (events[middle]!.offset < offset) low = middle + 1;
    else high = middle;
  }
  const found = events[low]?.offset === offset ? events[low] : undefined;
  const previous = events[low - 1];
  const next = events[found ? low + 1 : low];
  if (found) return { event: found, previous, next };
  const missing = !next ? "above" : !previous ? "below" : "gap";
  return { previous, next, missing };
}

/** The gap between two events' `createdAt` in the rows' notation (event-row.tsx `formatDelta`), never
 *  negative; none when either time does not parse. */
export function elapsedBetween(from: string, to: string): string | undefined {
  const ms = Date.parse(to) - Date.parse(from);
  if (Number.isNaN(ms)) return undefined;
  return formatDelta(Math.max(0, ms));
}

/** The raw event's keys, signal first: what happened and its payload before the envelope. */
const EVENT_KEY_ORDER = ["type", "payload", "metadata", "idempotencyKey", "offset", "createdAt"];

/** The event with its keys in `EVENT_KEY_ORDER`, then the rest (`source`, `path`) as they came. */
export function orderEventKeys(event: ContextViewEvent): Record<string, unknown> {
  const fields = event as unknown as Record<string, unknown>;
  const ordered: Record<string, unknown> = {};
  for (const key of EVENT_KEY_ORDER) if (key in fields) ordered[key] = fields[key];
  for (const [key, value] of Object.entries(fields))
    if (!EVENT_KEY_ORDER.includes(key)) ordered[key] = value;
  return ordered;
}

/** A keydown whose ← → belong to what has focus (a field, an editor), not to paging the log. */
export function isTypingTarget(target: EventTarget | null): boolean {
  if (!(target instanceof HTMLElement)) return false;
  return (
    target instanceof HTMLInputElement ||
    target instanceof HTMLTextAreaElement ||
    target instanceof HTMLSelectElement ||
    target.isContentEditable
  );
}

// The inspector: one event, whole, in a right-edge sheet (full width on a phone), paged through the
// loaded log, over the view's sorted array.
// - PAGING: Prev / Next and ← → move to the neighbouring event of the whole loaded log (not the
//   filter's), each a `state.event` patch, so the URL follows and
//   every step is a link. The keys are heard on the window in the capture phase: Base UI's popup
//   (our Sheet) stops ← → on bubble for its nested composites. A field or editor with focus keeps
//   its arrows; a modifier (⌘←, ⇧→) is never a page. ← on the oldest loaded event reads the page
//   below and steps onto it once it lands.
// - A LINK TO AN EVENT NOT LOADED (`?event=5` on a 100,000 event log, whose newest page is all that
//   is read) reads older pages until it is, rather than showing nothing; an offset no event has (an
//   ephemeral one, a typo) says so and offers its neighbours.
// - THE HEADER: the event's sentence (or short type; the full type on hover), `#offset · N loaded ·
//   when`, and the gap to the previous and to the next event (`+166ms · +28ms to next`).
// - THE BODY: a rich inspector when one is registered for the type (the message as prose, the
//   script as code), who and on what grant, then the raw event in the read-only CodeMirror block —
//   YAML first, keys signal first (type, payload, then the envelope), a YAML/JSON toggle, copy
//   either, fold, ⌘F search.
// - CLOSING keeps the last event painted through the sheet's exit slide, with paging off.
import { useEffect, useEffectEvent, useMemo, useState } from "react";
import { ChevronLeftIcon, ChevronRightIcon } from "lucide-react";
import {
  elapsedBetween,
  inspectedPlace,
  isTypingTarget,
  orderEventKeys,
} from "./event-inspector-log.ts";
import { actorLabel, shortEventType } from "./filters.tsx";
import {
  type ContextViewEvent,
  type EventInspectors,
  type EventRenderers,
  rendererFor,
} from "./types.tsx";
import { Button } from "#/components/ui/button.tsx";
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
} from "#/components/ui/sheet.tsx";
import { SerializedObjectCodeBlock } from "#/components/code-block.tsx";
import { Spinner } from "#/components/ui/spinner.tsx";

export function EventInspector({
  events,
  offset,
  older,
  renderers,
  inspectors,
  onNavigate,
  onClose,
}: {
  /** The loaded log, sorted by offset. */
  events: readonly ContextViewEvent[];
  /** The inspected offset (`state.event`); undefined = closed. */
  offset: number | undefined;
  /** Reading the log below what is loaded. */
  older: { loadOlder(): void; loading: boolean; exhausted: boolean };
  renderers?: EventRenderers;
  inspectors?: EventInspectors;
  /** Inspect another offset — a `state.event` patch. */
  onNavigate: (offset: number) => void;
  onClose: () => void;
}) {
  const open = offset !== undefined;
  // the last offset inspected, painted while the sheet slides out after `offset` went undefined
  const [shown, setShown] = useState(offset);
  if (offset !== undefined && offset !== shown) setShown(offset);
  const place = useMemo(
    () => (shown === undefined ? undefined : inspectedPlace(events, shown)),
    [events, shown],
  );
  const { event, previous, next, missing } = place || {};
  const olderLeft = !older.exhausted;
  // ← pressed on the oldest loaded event: the offset it was pressed on, until the page below lands
  const [steppingBackFrom, setSteppingBackFrom] = useState<number>();
  const stepBack = () => {
    if (previous) onNavigate(previous.offset);
    else if (olderLeft && shown !== undefined) {
      setSteppingBackFrom(shown);
      older.loadOlder();
    }
  };
  const stepForward = () => next && onNavigate(next.offset);
  useEffect(() => {
    if (steppingBackFrom === undefined) return;
    if (steppingBackFrom !== shown) setSteppingBackFrom(undefined);
    else if (previous) {
      setSteppingBackFrom(undefined);
      onNavigate(previous.offset);
    } else if (older.exhausted) setSteppingBackFrom(undefined);
  }, [steppingBackFrom, shown, previous, older.exhausted, onNavigate]);
  // a link to an event older than the loaded pages: read on down to it
  const readingDown = open && missing === "below" && olderLeft;
  useEffect(() => {
    if (readingDown && !older.loading) older.loadOlder();
  }, [readingDown, older]);

  const onKey = useEffectEvent((key: KeyboardEvent) => {
    if (key.altKey || key.ctrlKey || key.metaKey || key.shiftKey) return;
    if (isTypingTarget(key.target)) return;
    if (key.key === "ArrowLeft" && (previous || olderLeft)) {
      key.preventDefault();
      stepBack();
    } else if (key.key === "ArrowRight" && next) {
      key.preventDefault();
      stepForward();
    }
  });
  useEffect(() => {
    if (!open) return;
    const listener = (key: KeyboardEvent) => onKey(key);
    window.addEventListener("keydown", listener, true);
    return () => window.removeEventListener("keydown", listener, true);
  }, [open]);

  // a new object only when the event is another: CodeMirror rebuilds on a new document
  const raw = useMemo(() => (event ? orderEventKeys(event) : undefined), [event]);
  const sentence = event ? (rendererFor(renderers, event.type)?.(event) ?? null) : null;
  const body = event ? (rendererFor(inspectors, event.type)?.(event) ?? null) : null;
  const envelope: [label: string, value: string][] = event
    ? [
        ["Who", actorLabel(event)],
        ["From", event.source?.origin || ""],
        ["Grant", event.source?.grant || ""],
        [
          "Processor",
          event.source?.processor
            ? `${event.source.processor.slug}@${event.source.processor.version}`
            : "",
        ],
      ].filter((row): row is [string, string] => Boolean(row[1]))
    : [];
  const sincePrevious = event && previous && elapsedBetween(previous.createdAt, event.createdAt);
  const untilNext = event && next && elapsedBetween(event.createdAt, next.createdAt);
  return (
    <Sheet open={open} onOpenChange={(opened) => !opened && onClose()}>
      <SheetContent
        side="right"
        className="gap-0 p-0 data-[side=right]:w-full data-[side=right]:sm:max-w-3xl"
        inert={!open}
      >
        {shown === undefined ? null : (
          <>
            <SheetHeader className="shrink-0 pr-12">
              <SheetTitle className="line-clamp-2 text-sm [&_*]:inline" title={event?.type}>
                {!event
                  ? `Event #${String(shown)}`
                  : (sentence ?? <span className="font-mono">{shortEventType(event.type)}</span>)}
              </SheetTitle>
              <SheetDescription className="font-mono text-xs">
                #{shown}
                {event && sentence ? ` · ${shortEventType(event.type)}` : ""} ·{" "}
                {events.length.toLocaleString()} loaded
                {event ? ` · ${event.createdAt}` : ""}
              </SheetDescription>
            </SheetHeader>
            <div className="flex shrink-0 flex-wrap items-center gap-2 px-4 pb-3">
              <Button
                size="sm"
                variant="outline"
                disabled={!open || (!previous && !olderLeft)}
                onClick={stepBack}
              >
                {steppingBackFrom === undefined ? <ChevronLeftIcon /> : <Spinner />}
                Prev
              </Button>
              <Button size="sm" variant="outline" disabled={!open || !next} onClick={stepForward}>
                Next
                <ChevronRightIcon />
              </Button>
              <span className="hidden text-xs text-muted-foreground/70 sm:inline">
                ← → page the log
              </span>
              <span className="ml-auto flex items-center gap-2 font-mono text-[10px] text-muted-foreground">
                {sincePrevious ? (
                  <span title="Since the previous event">{sincePrevious}</span>
                ) : null}
                {sincePrevious && untilNext ? <span>·</span> : null}
                {untilNext ? <span title="Until the next event">{untilNext} to next</span> : null}
              </span>
            </div>
            <div className="flex min-h-0 flex-1 flex-col gap-4 overflow-y-auto border-t px-4 py-3">
              {!event ? (
                <p className="text-sm text-muted-foreground">
                  {readingDown ? (
                    <span className="flex items-center gap-2">
                      <Spinner /> Reading older events to reach #{shown}…
                    </span>
                  ) : missing === "above" ? (
                    `No event #${String(shown)} yet.`
                  ) : (
                    `No event has offset #${String(shown)}. Prev and Next go to its neighbours.`
                  )}
                </p>
              ) : (
                <>
                  {body ? <div className="min-w-0">{body}</div> : null}
                  {envelope.length > 0 ? (
                    <dl className="grid grid-cols-[auto_1fr] gap-x-4 gap-y-1 text-xs">
                      {envelope.map(([label, value]) => (
                        <div key={label} className="contents">
                          <dt className="text-muted-foreground">{label}</dt>
                          <dd className="min-w-0 truncate font-mono" title={value}>
                            {value}
                          </dd>
                        </div>
                      ))}
                    </dl>
                  ) : null}
                  <div className="min-w-0">
                    <SerializedObjectCodeBlock data={raw} />
                  </div>
                </>
              )}
            </div>
          </>
        )}
      </SheetContent>
    </Sheet>
  );
}

// One row of the stream, ONE line that never runs past the view on a desktop (two on a phone), read
// like a log, left to right in fixed columns: `#offset` in a muted gutter sized to the log's largest
// offset (`--offset-width`, set by the view), the clock, the gap since the row before (blank under a
// second; coloured by its size, so a long pause runs hot), the body, and who — when it is not who
// acted on the row before. No rule between rows: the hover and the inspected row's 2px bar are
// enough. On a phone the body comes first and the rest is one muted line under it. The body in
// Pretty is a renderer's sentence for the type (the platform's own come with theirs — the
// lifecycle's are ordinary muted sentences, a wake purple), else the type and a glance at the
// payload's fields; Pretty + raw adds the raw line under it; Raw is the raw line, the type in a
// fixed column. What a line cuts the inspector (click) shows whole.
import { memo } from "react";
import { cn } from "cn";
import { actorLabel, payloadPreview, payloadSummary, shortEventType } from "./filters.tsx";
import {
  type ContextViewEvent,
  type ContextViewMode,
  type EventRenderers,
  rendererFor,
} from "./types.tsx";

/** The row's clock: `19:36:58` in the reader's zone, always the 24-hour cycle — eight characters
 *  that fit the fixed column in every locale (a 12-hour locale's ` PM` would run into the delta). */
export function formatClockTime(ms: number): string {
  return new Date(ms).toLocaleTimeString(undefined, {
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hourCycle: "h23",
  });
}

/** `+950ms`, `+3.2s`, `+1m40s`, `+2h5m` — the compact gap between two rows. */
export function formatDelta(ms: number): string {
  if (ms < 1_000) return `+${String(ms)}ms`;
  if (ms < 60_000) return `+${(Math.floor(ms / 100) / 10).toFixed(1).replace(/\.0$/, "")}s`;
  const seconds = Math.floor(ms / 1_000);
  if (seconds < 3_600) return `+${String(Math.floor(seconds / 60))}m${String(seconds % 60)}s`;
  const minutes = Math.floor(seconds / 60);
  return `+${String(Math.floor(minutes / 60))}h${String(minutes % 60)}m`;
}

/** The gap's colour by its size: a second or more is green, then amber, orange, and a pause of
 *  ten minutes or more red — where the log went quiet stands out. */
function deltaColor(ms: number): string {
  if (ms < 10_000) return "text-emerald-600";
  if (ms < 60_000) return "text-amber-600";
  if (ms < 600_000) return "text-orange-600";
  return "text-red-600";
}

/** The frame every row shares: full width, the columns on one line from `sm` (a phone wraps the
 *  body above the rest), 26px tall, the hover, the inspected row's left bar. Rows are buttons
 *  (inspect, or open a fold). */
export const rowClass = (selected?: boolean) =>
  cn(
    "flex w-full min-w-0 flex-wrap items-baseline gap-x-3.5 px-3 sm:px-4 py-[3px] text-left hover:bg-muted/60 max-sm:gap-x-2 max-sm:py-1.5 sm:flex-nowrap",
    selected && "bg-muted shadow-[inset_2px_0_0_var(--color-foreground)] hover:bg-muted",
  );

const OFFSET =
  "shrink-0 font-mono text-[11px] text-muted-foreground/60 tabular-nums sm:w-[var(--offset-width,6ch)] sm:text-right";
const CLOCK = "shrink-0 font-mono text-[11px] text-muted-foreground tabular-nums sm:w-[8ch]";
const GAP =
  "shrink-0 font-mono text-[11px] tabular-nums max-sm:empty:hidden sm:w-[7ch] sm:text-right";

/** `#123`, right-aligned in the gutter the view sizes to its largest offset (`--offset-width`). */
export function RowOffset({ offset }: { offset: number }) {
  return <span className={OFFSET}>#{offset}</span>;
}

/** The empty columns before the body (the offset, and with `times` the clock and the gap), so a
 *  line that is not an event — a day, the top of the log, the composer — starts where they do. */
export function RowGutter({ times }: { times?: boolean }) {
  return (
    <>
      <span aria-hidden className={cn(OFFSET, "max-sm:hidden")} />
      {times ? (
        <>
          <span aria-hidden className={cn(CLOCK, "max-sm:hidden")} />
          <span aria-hidden className={cn(GAP, "max-sm:hidden")} />
        </>
      ) : null}
    </>
  );
}

/** Who acted, when it changes hands: the right edge on a desktop, the meta line on a phone. */
export function RowWho({ who }: { who: string }) {
  return (
    <span className="max-w-48 shrink-0 truncate text-xs text-muted-foreground max-sm:font-mono max-sm:text-[11px] sm:ml-auto">
      {who}
    </span>
  );
}

/** The clock and the gap since the row before (from its LAST moment, so a fold's gap is the idle
 *  time between rows, not inside one): two columns, the gap blank under a second. */
export function RowTimes({
  event,
  previous,
}: {
  event: ContextViewEvent;
  previous?: ContextViewEvent;
}) {
  const at = Date.parse(event.createdAt);
  const gap = previous ? Math.max(0, at - Date.parse(previous.createdAt)) : undefined;
  return (
    <>
      <time dateTime={event.createdAt} title={new Date(at).toISOString()} className={CLOCK}>
        {formatClockTime(at)}
      </time>
      <span className={cn(GAP, gap !== undefined && deltaColor(gap))} title="Since the row before">
        {gap === undefined || gap < 1_000 ? "" : formatDelta(gap)}
      </span>
    </>
  );
}

/** The body column: first on a phone, where it takes the whole first line. */
export const rowBody = "min-w-0 flex-1 max-sm:order-first max-sm:basis-full";

/** The raw line: the type and the payload's JSON, one line. */
export function RawLine({ event, className }: { event: ContextViewEvent; className?: string }) {
  const glance = payloadPreview(event.payload);
  return (
    <span
      className={cn(
        "flex min-w-0 gap-3 font-mono text-xs leading-5 text-muted-foreground",
        className,
      )}
    >
      <span className="w-[26ch] shrink-0 truncate text-foreground/85">
        {shortEventType(event.type)}
      </span>
      {glance ? <span className="min-w-0 truncate">{glance}</span> : null}
    </span>
  );
}

/** The sentence: a renderer's for the type, else the type with a glance at the payload's fields.
 *  Every child is forced inline so the line truncates as one — a renderer's <strong> and <span> too. */
export function EventSentence({
  event,
  renderers,
  className,
}: {
  event: ContextViewEvent;
  renderers?: EventRenderers;
  className?: string;
}) {
  const rich = rendererFor(renderers, event.type)?.(event) ?? null;
  const glance = payloadSummary(event.payload);
  return (
    <span
      className={cn(
        // a phone gets two lines, a desktop one — never a third, never a sideways scroll
        "block max-h-10 min-w-0 overflow-hidden text-sm leading-5 whitespace-normal sm:max-h-none sm:truncate [&_*]:inline",
        className,
      )}
    >
      {rich ?? (
        <>
          <span className="font-mono text-xs text-foreground/80">{shortEventType(event.type)}</span>
          {glance ? <span className="ml-2 text-xs text-muted-foreground">{glance}</span> : null}
        </>
      )}
    </span>
  );
}

export const EventRow = memo(function EventRow({
  event,
  previous,
  renderers,
  mode,
  showWho,
  quiet,
  selected,
  onOpen,
}: {
  event: ContextViewEvent;
  previous?: ContextViewEvent;
  renderers?: EventRenderers;
  mode: ContextViewMode;
  /** Whether to name who acted — false when the row before was theirs too. */
  showWho: boolean;
  /** Housekeeping expanded out of its fold reads muted. */
  quiet?: boolean;
  selected?: boolean;
  onOpen: (offset: number) => void;
}) {
  const who = actorLabel(event);
  return (
    <button
      type="button"
      onClick={() => onOpen(event.offset)}
      data-offset={event.offset}
      className={cn(rowClass(selected), quiet && "text-muted-foreground")}
    >
      <RowOffset offset={event.offset} />
      <RowTimes event={event} previous={previous} />
      <span className={rowBody}>
        {mode === "raw" ? (
          <RawLine event={event} />
        ) : (
          <EventSentence event={event} renderers={renderers} />
        )}
        {mode === "pretty-raw" ? <RawLine event={event} className="mt-0.5 text-[11px]" /> : null}
      </span>
      {showWho && who ? <RowWho who={who} /> : null}
    </button>
  );
});

// The folded log as ONE virtual list in its own scroll region (TanStack Virtual): only the rows in
// view, plus an overscan, are in the DOM, so 100,000 events scroll like 100. Opened folds list their
// members as rows of their own. While there is more log below what is loaded, row 0 is its top:
// "Load older events", or a spinner while a page is read; once the whole log is loaded there is no
// such row — `#1` says it is the start.
//
// The scheme: the stick (stick-to-bottom.ts) owns the tail in DOM
// truth, so followOnAppend is off; `anchorTo: "end"` keeps the row at the top of the view where it is when rows
// arrive above it (an older page) or below it (a reader in history is never yanked); rows are keyed
// by offset, never by index, which is what lets that anchor find its row again after a prepend.
// Nearing the top of what is loaded (the reader scrolled there, or the log is shorter than the
// view) asks for the page below it. Off the tail, a "Jump to latest" pill (with how many rows came
// in since) pins it again. The inspected row is scrolled into view once per inspection (the
// inspector paging the log, a link to an event).
import { useCallback, useEffect, useMemo, useRef, type ReactNode } from "react";
import { ArrowDownIcon } from "lucide-react";
import { useVirtualizer } from "@tanstack/react-virtual";
import { EventRow, RowGutter } from "./event-row.tsx";
import { DaySeparator, HousekeepingRow, RepeatRow } from "./feed-rows.tsx";
import { actorLabel } from "./filters.tsx";
import { type FeedItem, lastEventOf } from "./folds.tsx";
import { useStickToBottom } from "./stick-to-bottom.ts";
import type { ContextViewEvent, ContextViewMode, EventRenderers } from "./types.tsx";
import { Spinner } from "#/components/ui/spinner.tsx";

/** A member of an opened fold, listed under it. */
type MemberRow = {
  kind: "member";
  key: string;
  event: ContextViewEvent;
  previous?: ContextViewEvent;
  /** The fold was housekeeping: the member reads muted. */
  quiet: boolean;
};

/** Older pages are asked for when the top of the view is within this many rows of row 0. */
const LOAD_OLDER_WITHIN_ROWS = 40;

export function FeedList({
  items,
  namedBefore,
  mode,
  renderers,
  inspected,
  onInspect,
  opened,
  onToggle,
  older,
  followTail,
  empty,
}: {
  items: readonly FeedItem[];
  /** `whoBefore(items)`: a row names who acted only when it changes against this. */
  namedBefore: readonly string[];
  mode: ContextViewMode;
  renderers: EventRenderers;
  inspected?: number;
  onInspect: (offset: number) => void;
  opened: ReadonlySet<string>;
  onToggle: (itemKey: string) => void;
  older: { loadOlder(): void; loading: boolean; exhausted: boolean };
  /** Each change pins the view to the tail again, wherever the reader was (the view's own append:
   *  the next rows to arrive are the person's, and they land in view). */
  followTail?: number;
  /** What shows when there are no rows: the empty log, a filter matching nothing, the first read. */
  empty: ReactNode;
}) {
  // Opened folds add their members after them. Nothing opened (the common case) lists the items
  // themselves, with no pass over 100,000 of them.
  const { rows, itemIndexOf } = useMemo(() => {
    if (opened.size === 0)
      return { rows: items as readonly (FeedItem | MemberRow)[], itemIndexOf: null };
    const rows: (FeedItem | MemberRow)[] = [];
    const itemIndexOf: number[] = [];
    items.forEach((item, index) => {
      rows.push(item);
      itemIndexOf.push(index);
      if (item.kind === "day" || item.kind === "event" || !opened.has(item.key)) return;
      item.events.forEach((event, at) => {
        rows.push({
          kind: "member",
          key: `${item.key}/${String(event.offset)}`,
          event,
          previous: at === 0 ? lastEventOf(items[index - 1]) : item.events[at - 1],
          quiet: item.kind === "housekeeping",
        });
        itemIndexOf.push(-1);
      });
    });
    return { rows, itemIndexOf };
  }, [items, opened]);

  const scrollRef = useRef<HTMLDivElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);
  const { stuckRef, stuck, stick, release } = useStickToBottom({
    scrollElementRef: scrollRef,
    contentElementRef: contentRef,
  });
  useEffect(() => {
    if (followTail) stick();
  }, [followTail, stick]);
  const { loadOlder, loading, exhausted } = older;
  // while more log lies below what is loaded, virtual index 0 is the top row and row i is virtual
  // index i + 1; once it is all loaded, row i is index i
  const top = exhausted ? 0 : 1;
  const getItemKey = useCallback(
    (index: number) => (index < top ? "top" : rows[index - top]!.key),
    [rows, top],
  );
  const estimateSize = useCallback(
    (index: number) => {
      const row = index < top ? undefined : rows[index - top];
      if (!row) return 28;
      // every one-line row is 26px (event-row.tsx `rowClass`); a day 36; both lines 42
      if (row.kind === "day") return 36;
      if (row.kind === "member") return row.quiet ? 26 : 42;
      if (row.kind !== "event") return 26;
      return mode === "pretty-raw" ? 42 : 26;
    },
    [rows, mode, top],
  );
  const virtualizer = useVirtualizer({
    count: rows.length + top,
    getScrollElement: () => scrollRef.current,
    estimateSize,
    getItemKey,
    anchorTo: "end",
    // the stick owns the tail: the library's follow is gated on its own isAtEnd(), which drifts
    // from the DOM, and two writers fight (its reconcile loop is uncancellable, TanStack/virtual#1221)
    followOnAppend: false,
    scrollEndThreshold: 80,
    overscan: 16,
    // vertical breathing room lives HERE, not as wrapper padding the virtualizer cannot see (that
    // would shift its coordinates off the scroller's and strand the end anchor above the bottom)
    paddingStart: 4,
    paddingEnd: 8,
  });
  const virtualItems = virtualizer.getVirtualItems();

  // The inspected row, scrolled into view once per inspection (the inspector's paging, a link's
  // `event`) — never again as rows arrive, so a reader who scrolled away from it stays there.
  const revealRef = useRef<number | undefined>(undefined);
  useEffect(() => {
    revealRef.current = inspected;
  }, [inspected]);
  useEffect(() => {
    const offset = revealRef.current;
    if (offset === undefined || rows.length === 0) return;
    revealRef.current = undefined;
    const index = rows.findIndex((row) => rowOffset(row) === offset);
    if (index < 0) return; // folded away, or not loaded: the inspector shows it all the same
    release();
    virtualizer.scrollToIndex(index + top, { align: "auto" });
  });
  // rows that came in since the reader left the tail, for the pill
  const lastOffset = rows.length > 0 ? lastOffsetOf(rows[rows.length - 1]!) : 0;
  const leftAtRef = useRef(lastOffset);
  if (stuck) leftAtRef.current = lastOffset;
  let arrived = 0;
  if (!stuck)
    for (let at = rows.length - 1; at >= 0 && lastOffsetOf(rows[at]!) > leftAtRef.current; at--)
      if (rows[at]!.kind !== "day") arrived += 1;

  const firstInView = virtualItems[0]?.index ?? 0;
  useEffect(() => {
    const scroller = scrollRef.current;
    if (!scroller || loading || exhausted || rows.length === 0) return;
    // near the top — but only once the reader left the tail (on opening, the view is at the top for
    // a frame before the stick pins it to the bottom), or when the whole log loaded fits the view
    const fits = scroller.scrollHeight <= scroller.clientHeight;
    if (firstInView < LOAD_OLDER_WITHIN_ROWS && (fits || !stuckRef.current)) loadOlder();
  }, [firstInView, loading, exhausted, loadOlder, rows.length, stuckRef]);

  return (
    <div className="relative flex min-h-0 flex-1 flex-col">
      <div
        ref={scrollRef}
        role="log"
        aria-label="Events"
        className="min-h-0 flex-1 overflow-y-auto overscroll-contain"
      >
        {rows.length === 0 ? (
          empty
        ) : (
          <div
            ref={contentRef}
            className="relative w-full"
            style={{ height: virtualizer.getTotalSize() }}
          >
            {virtualItems.map((virtualItem) => (
              <div
                key={virtualItem.key}
                data-index={virtualItem.index}
                ref={virtualizer.measureElement}
                className="absolute top-0 left-0 w-full"
                style={{ transform: `translateY(${String(virtualItem.start)}px)` }}
              >
                {virtualItem.index < top ? (
                  <OlderRow loading={loading} onLoad={loadOlder} />
                ) : (
                  renderRow(virtualItem.index - top)
                )}
              </div>
            ))}
          </div>
        )}
      </div>
      {stuck || rows.length === 0 ? null : (
        <button
          type="button"
          onClick={stick}
          className="absolute bottom-3 left-1/2 flex -translate-x-1/2 items-center gap-1.5 rounded-full border bg-background px-3 py-1 text-xs text-muted-foreground shadow-sm hover:text-foreground"
        >
          <ArrowDownIcon className="size-3.5" />
          Jump to latest
          {arrived > 0 ? (
            <span className="tabular-nums text-foreground">· {arrived} new</span>
          ) : null}
        </button>
      )}
    </div>
  );

  function renderRow(index: number) {
    const row = rows[index]!;
    if (row.kind === "member")
      return (
        <EventRow
          event={row.event}
          previous={row.previous}
          renderers={renderers}
          mode={row.quiet ? "pretty" : "pretty-raw"}
          showWho={false}
          quiet={row.quiet}
          selected={inspected === row.event.offset}
          onOpen={onInspect}
        />
      );
    if (row.kind === "day") return <DaySeparator date={row.date} />;
    const itemIndex = itemIndexOf ? itemIndexOf[index]! : index;
    const previous = lastEventOf(items[itemIndex - 1]);
    const first = row.kind === "event" ? row.event : row.events[0]!;
    // who acted is named when it changes hands: against the last row that WAS someone's (the
    // platform's housekeeping between two of a person's rows names nobody), afresh each day
    const showWho = actorLabel(first) !== namedBefore[itemIndex];
    if (row.kind === "repeat")
      return (
        <RepeatRow
          itemKey={row.key}
          events={row.events}
          previous={previous}
          renderers={renderers}
          showWho={showWho}
          open={opened.has(row.key)}
          onToggle={onToggle}
        />
      );
    if (row.kind === "housekeeping")
      return (
        <HousekeepingRow
          itemKey={row.key}
          events={row.events}
          previous={previous}
          open={opened.has(row.key)}
          onToggle={onToggle}
        />
      );
    return (
      <EventRow
        event={row.event}
        previous={previous}
        renderers={renderers}
        mode={mode}
        showWho={showWho}
        selected={inspected === row.event.offset}
        onOpen={onInspect}
      />
    );
  }
}

/** The event a row opens in the inspector: an event's, an opened fold member's; none for a day
 *  mark or a fold (they open in place). */
function rowOffset(row: FeedItem | MemberRow): number | undefined {
  return row.kind === "event" || row.kind === "member" ? row.event.offset : undefined;
}

/** The last offset a row covers (a day mark: 0 — it never ends the list). */
function lastOffsetOf(row: FeedItem | MemberRow): number {
  return row.kind === "member" ? row.event.offset : (lastEventOf(row)?.offset ?? 0);
}

/** The top of what is loaded, while there is more below it: a way to read the page below, or that
 *  page being read — in the body column, one height either way, so the rows below never shift. */
function OlderRow({ loading, onLoad }: { loading: boolean; onLoad: () => void }) {
  return (
    <div className="flex h-7 items-center gap-x-3.5 px-3 sm:px-4 text-xs text-muted-foreground">
      <RowGutter times />
      {loading ? (
        <span className="flex items-center gap-2">
          <Spinner /> Loading older events…
        </span>
      ) : (
        <button type="button" onClick={onLoad} className="underline-offset-2 hover:underline">
          Load older events
        </button>
      )}
    </div>
  );
}

// The rows that are not one event: the day mark (a plain word over the clock column, no rule), a
// repeated fact with a small count, a run of the platform's housekeeping folded into one quiet line
// ("2 housekeeping · woke, subscription"). The two folds open in place on a click: the feed lists
// their members under them as rows of their own (feed-list.tsx), each opening the inspector like
// any row. Memoised, like every row: the feed re-renders on every scroll frame.
import { memo } from "react";
import { ChevronDownIcon, ChevronRightIcon } from "lucide-react";
import { cn } from "cn";
import { housekeepingSummary } from "./core-renderers.tsx";
import {
  EventSentence,
  formatClockTime,
  RowGutter,
  RowOffset,
  RowTimes,
  RowWho,
  rowBody,
  rowClass,
} from "./event-row.tsx";
import { actorLabel } from "./filters.tsx";
import type { ContextViewEvent, EventRenderers } from "./types.tsx";

export const DaySeparator = memo(function DaySeparator({ date }: { date: Date }) {
  const today = new Date();
  const yesterday = new Date(today.getTime() - 86_400_000);
  const label =
    date.toDateString() === today.toDateString()
      ? "Today"
      : date.toDateString() === yesterday.toDateString()
        ? "Yesterday"
        : date.toLocaleDateString(undefined, {
            weekday: "short",
            day: "numeric",
            month: "short",
            year: date.getFullYear() === today.getFullYear() ? undefined : "numeric",
          });
  return (
    <div className="flex items-baseline gap-x-3.5 px-3 sm:px-4 pt-3 pb-1">
      <RowGutter />
      <span className="text-xs font-semibold text-foreground/75">{label}</span>
    </div>
  );
});

function Chevron({ open }: { open: boolean }) {
  return open ? (
    <ChevronDownIcon className="size-3 shrink-0 self-center text-muted-foreground/70" />
  ) : (
    <ChevronRightIcon className="size-3 shrink-0 self-center text-muted-foreground/70" />
  );
}

/** The same fact `events.length` times in a row: its sentence once, the count, the span of time. */
export const RepeatRow = memo(function RepeatRow({
  itemKey,
  events,
  previous,
  renderers,
  showWho,
  open,
  onToggle,
}: {
  /** The fold's key, handed back to `onToggle`. */
  itemKey: string;
  events: ContextViewEvent[];
  previous?: ContextViewEvent;
  renderers?: EventRenderers;
  showWho: boolean;
  open: boolean;
  onToggle: (itemKey: string) => void;
}) {
  const first = events[0]!;
  const last = events.at(-1)!;
  const who = actorLabel(first);
  return (
    <button
      type="button"
      onClick={() => onToggle(itemKey)}
      aria-expanded={open}
      className={rowClass()}
    >
      <RowOffset offset={first.offset} />
      <RowTimes event={first} previous={previous} />
      <span className={cn(rowBody, "flex items-baseline gap-1.5")}>
        <EventSentence event={first} renderers={renderers} className="min-w-0" />
        <span
          className="shrink-0 text-[11px] text-muted-foreground tabular-nums"
          title={`${String(events.length)} times, ${formatClockTime(Date.parse(first.createdAt))} – ${formatClockTime(Date.parse(last.createdAt))}`}
        >
          ×{events.length}
        </span>
        <Chevron open={open} />
      </span>
      {showWho && who ? <RowWho who={who} /> : null}
    </button>
  );
});

/** A run of the platform's housekeeping: one quiet line saying how much of what; open for the rows. */
export const HousekeepingRow = memo(function HousekeepingRow({
  itemKey,
  events,
  previous,
  open,
  onToggle,
}: {
  /** The fold's key, handed back to `onToggle`. */
  itemKey: string;
  events: ContextViewEvent[];
  previous?: ContextViewEvent;
  open: boolean;
  onToggle: (itemKey: string) => void;
}) {
  const first = events[0]!;
  return (
    <button
      type="button"
      onClick={() => onToggle(itemKey)}
      aria-expanded={open}
      className={cn(rowClass(), "text-muted-foreground")}
    >
      <RowOffset offset={first.offset} />
      <RowTimes event={first} previous={previous} />
      <span className={cn(rowBody, "flex items-baseline gap-1 text-[13px]")}>
        <Chevron open={open} />
        <span className="truncate">
          {events.length} housekeeping · {housekeepingSummary(events.map((e) => e.type))}
        </span>
      </span>
    </button>
  );
});

// The context view's filter row: a search box that takes the focus when the row opens (Escape empties it), the log's types
// as chips with their counts (a ticked type the loaded log lacks still shows, at 0, so it can be
// unticked), an offset range `from`–`to`, and one "clear". Every value is the view's URL state; this
// only renders it and hands back patches.
import { useCallback } from "react";
import { SearchIcon } from "lucide-react";
import { cn } from "cn";
import { FILTER_CLEARED, type ContextViewState } from "./context-view-search.ts";
import { offsetBound, shortEventType, typeChips, type ContextViewFilter } from "./filters.tsx";
import { InputGroup, InputGroupAddon, InputGroupInput } from "#/components/ui/input-group.tsx";

export function FilterRow({
  filter,
  counts,
  narrowed,
  partial,
  loaded,
  onStateChange,
}: {
  filter: ContextViewFilter;
  /** The loaded log's types with their counts, most frequent first. */
  counts: readonly [type: string, count: number][];
  /** Whether the filter narrows anything: "clear" shows. */
  narrowed: boolean;
  /** Older pages exist that the filter does not search. */
  partial: boolean;
  /** How many events are loaded, as the strip says it. */
  loaded: string;
  onStateChange: (patch: Partial<ContextViewState>) => void;
}) {
  const focusOnMount = useCallback((element: HTMLInputElement | null) => element?.focus(), []);
  const toggleType = (type: string) => {
    const next = filter.types.has(type)
      ? [...filter.types].filter((held) => held !== type)
      : [...filter.types, type];
    onStateChange({ types: next.length > 0 ? next : undefined });
  };
  return (
    <div className="flex flex-col gap-2" data-slot="filter-row">
      <div className="flex flex-wrap items-center gap-x-3 gap-y-2">
        <InputGroup className="h-8 min-w-48 flex-1">
          <InputGroupAddon>
            <SearchIcon />
          </InputGroupAddon>
          <InputGroupInput
            ref={focusOnMount}
            value={filter.query}
            onChange={(event) => onStateChange({ q: event.target.value || undefined })}
            onKeyDown={(event) => {
              if (event.key === "Escape" && filter.query) onStateChange({ q: undefined });
            }}
            placeholder="Search type or payload"
            aria-label="Search type or payload"
            className="text-base sm:text-sm"
          />
        </InputGroup>
        <div
          className="flex items-center gap-1 text-xs text-muted-foreground"
          title="Only the events between these offsets, inclusive"
        >
          <span>from</span>
          <OffsetInput
            label="From offset"
            value={filter.from}
            onChange={(from) => onStateChange({ from })}
          />
          <span>to</span>
          <OffsetInput
            label="To offset"
            value={filter.to}
            onChange={(to) => onStateChange({ to })}
          />
        </div>
      </div>
      <div className="flex max-h-32 flex-wrap gap-1 overflow-y-auto">
        {typeChips(counts, filter.types).map(([type, count]) => (
          <button
            key={type}
            type="button"
            onClick={() => toggleType(type)}
            aria-pressed={filter.types.has(type)}
            title={type}
            className={cn(
              "rounded px-1.5 py-0.5 font-mono text-xs hover:bg-muted",
              filter.types.has(type) ? "bg-muted text-foreground" : "text-muted-foreground",
            )}
          >
            {shortEventType(type)} <span className="tabular-nums">{count.toLocaleString()}</span>
          </button>
        ))}
        {narrowed ? (
          <button
            type="button"
            onClick={() => onStateChange(FILTER_CLEARED)}
            className="px-1.5 py-0.5 text-xs text-muted-foreground underline-offset-2 hover:underline"
          >
            clear
          </button>
        ) : null}
      </div>
      {partial ? (
        <p className="text-xs text-muted-foreground">
          The filter searches the {loaded} events loaded; scroll up to load older ones.
        </p>
      ) : null}
    </div>
  );
}

/** One end of the offset range: blank = open, a number = that offset (offsetBound). */
function OffsetInput({
  label,
  value,
  onChange,
}: {
  label: string;
  value: number | undefined;
  onChange: (value: number | undefined) => void;
}) {
  return (
    <input
      inputMode="numeric"
      aria-label={label}
      placeholder="#"
      value={value ?? ""}
      onChange={(event) => {
        const bound = offsetBound(event.target.value);
        if (bound !== null) onChange(bound);
      }}
      className="h-7 w-16 rounded-md border bg-background px-1.5 text-center font-mono text-base tabular-nums sm:text-xs outline-none focus-visible:ring-1 focus-visible:ring-ring"
    />
  );
}

// Filtering the log, as pure functions: by type (the set left ticked), by a text query over the
// type and the payload's JSON, by the actor who appended, by an offset range (`from`/`to`). Plus the two short forms every row uses.
// `refilter` and `recount` follow a log that grows at either end without passing over all of it
// again (folds.tsx `growthOf`): a JSON.stringify per event per append is too slow at 100,000.
import { growthOf } from "./folds.tsx";
import { isRecord } from "./renderer-helpers.tsx";
import type { ContextViewEvent } from "./types.tsx";

export type ContextViewFilter = {
  query: string;
  /** Event types to show; empty = all. */
  types: ReadonlySet<string>;
  /** An actor id to narrow to (their events only). */
  actor?: string;
  /** The lowest offset shown, inclusive. */
  from?: number;
  /** The highest offset shown, inclusive. */
  to?: number;
};

export function filterEvents(
  events: readonly ContextViewEvent[],
  filter: ContextViewFilter,
): ContextViewEvent[] {
  const query = filter.query.trim().toLowerCase();
  return events.filter((event) => {
    if (filter.types.size > 0 && !filter.types.has(event.type)) return false;
    if (filter.actor && event.source?.principal?.actor !== filter.actor) return false;
    if (filter.from !== undefined && event.offset < filter.from) return false;
    if (filter.to !== undefined && event.offset > filter.to) return false;
    if (!query) return true;
    return (
      event.type.toLowerCase().includes(query) ||
      JSON.stringify(event.payload ?? null)
        .toLowerCase()
        .includes(query)
    );
  });
}

/** Whether a filter narrows anything. */
export const narrows = (filter: ContextViewFilter): boolean =>
  Boolean(filter.query.trim()) ||
  filter.types.size > 0 ||
  Boolean(filter.actor) ||
  filter.from !== undefined ||
  filter.to !== undefined;

/** Whether two filters narrow the same way (the view's filter is rebuilt from the URL on every
 *  change of it, the inspected event's too). */
function sameFilter(a: ContextViewFilter, b: ContextViewFilter): boolean {
  return (
    a.query.trim() === b.query.trim() &&
    a.actor === b.actor &&
    a.from === b.from &&
    a.to === b.to &&
    a.types.size === b.types.size &&
    [...a.types].every((type) => b.types.has(type))
  );
}

/** A filtered log and what it filtered, for the next `refilter`. */
export type Filtered = {
  events: readonly ContextViewEvent[];
  filter: ContextViewFilter;
  shown: readonly ContextViewEvent[];
};

/** `filterEvents`, re-using `previous` where the log only grew at one end and the filter is the
 *  same: only the added events are filtered. No filter shows the log itself (the same array, so a
 *  fold of it sees the log's own growth). */
export function refilter(
  previous: Filtered | undefined,
  events: readonly ContextViewEvent[],
  filter: ContextViewFilter,
): Filtered {
  if (!narrows(filter)) return { events, filter, shown: events };
  const growth =
    previous && narrows(previous.filter) && sameFilter(previous.filter, filter)
      ? growthOf(previous.events, events)
      : null;
  if (previous && growth && "end" in growth)
    return {
      events,
      filter,
      shown:
        growth.end.length === 0
          ? previous.shown
          : previous.shown.concat(filterEvents(growth.end, filter)),
    };
  if (previous && growth && "start" in growth)
    return { events, filter, shown: filterEvents(growth.start, filter).concat(previous.shown) };
  return { events, filter, shown: filterEvents(events, filter) };
}

/** Every type in the log with how often it occurs, most frequent first. */
export function typeCounts(events: readonly ContextViewEvent[]): [type: string, count: number][] {
  return sortedCounts(countTypes(new Map(), events));
}

/** A log's type counts and the log, for the next `recount`. */
export type TypeCounts = { events: readonly ContextViewEvent[]; counts: Map<string, number> };

/** The type counts of `events`, counting only what was added where the log only grew at one end. */
export function recount(
  previous: TypeCounts | undefined,
  events: readonly ContextViewEvent[],
): TypeCounts {
  const growth = previous ? growthOf(previous.events, events) : null;
  if (previous && growth) {
    const added = "end" in growth ? growth.end : growth.start;
    if (added.length === 0) return { events, counts: previous.counts };
    return { events, counts: countTypes(new Map(previous.counts), added) };
  }
  return { events, counts: countTypes(new Map(), events) };
}

function countTypes(counts: Map<string, number>, events: readonly ContextViewEvent[]) {
  for (const event of events) counts.set(event.type, (counts.get(event.type) ?? 0) + 1);
  return counts;
}

/** Counts by type as the filter row lists them: most frequent first, ties by name. */
export function sortedCounts(counts: Map<string, number>): [type: string, count: number][] {
  return [...counts.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
}

/** The type chips of the filter row: the log's counts, then every ticked type the loaded log does
 *  not hold (a link's `types`, a type only in older pages) with a count of 0 — so a selection that
 *  hides everything can still be seen and unticked. */
export function typeChips(
  counts: readonly [type: string, count: number][],
  ticked: ReadonlySet<string>,
): [type: string, count: number][] {
  const listed = new Set(counts.map(([type]) => type));
  const absent = [...ticked].filter((type) => !listed.has(type)).sort();
  return [...counts, ...absent.map((type): [string, number] => [type, 0])];
}

/** An offset box's text as a bound: blank = no bound, a number = that offset (a negative clamped to
 *  0, a fraction cut), anything else = no change (`null`), so a stray key never empties the feed. */
export function offsetBound(text: string): number | undefined | null {
  const trimmed = text.trim();
  if (trimmed === "") return undefined;
  const parsed = Number(trimmed.replace(/^#/, ""));
  return Number.isFinite(parsed) ? Math.max(0, Math.trunc(parsed)) : null;
}

/** The event type without its `events.iterate.com/` prefix. */
export const shortEventType = (type: string): string => type.replace(/^events\.iterate\.com\//, "");

/** The payload as one line, cut to `max` characters — the row's glance at the body. */
export function payloadPreview(payload: unknown, max = 140): string {
  if (payload === undefined) return "";
  const text = JSON.stringify(payload);
  return text.length > max ? `${text.slice(0, max - 1)}…` : text;
}

/** The payload's top-level fields as one human line — `key value · key value` — for a type no
 *  renderer names: strings to their first line, arrays to their length, objects to their keys. */
export function payloadSummary(payload: unknown, max = 120): string {
  if (payload === undefined) return "";
  if (Array.isArray(payload))
    return `${String(payload.length)} item${payload.length === 1 ? "" : "s"}`;
  if (!isRecord(payload)) return valueGlance(payload);
  const parts: string[] = [];
  for (const [key, value] of Object.entries(payload)) {
    if (parts.length === 5) {
      parts.push("…");
      break;
    }
    parts.push(`${key} ${valueGlance(value)}`);
  }
  const text = parts.join(" · ");
  return text.length > max ? `${text.slice(0, max - 1)}…` : text;
}

/** One value inside the line: a string's first line, an array's length, an object's keys, else JSON. */
function valueGlance(value: unknown): string {
  if (typeof value === "string") {
    const line = value.split("\n")[0] || "";
    return line.length > 48 ? `${line.slice(0, 47)}…` : line;
  }
  if (Array.isArray(value)) return `[${String(value.length)}]`;
  if (isRecord(value)) {
    const keys = Object.keys(value);
    return `{${keys.slice(0, 3).join(", ")}${keys.length > 3 ? ", …" : ""}}`;
  }
  return String(JSON.stringify(value)); // numbers, booleans, null — and "undefined" for a hole
}

/** Who appended: the email when the stamp has one, else the actor id; "" for the platform's own. */
export const actorLabel = (event: ContextViewEvent): string =>
  event.source?.principal?.email || event.source?.principal?.actor || "";

// The log folded for reading, as a pure function: day separators wherever the date turns; in
// Pretty, a run of the platform's housekeeping becomes one quiet row and a fact repeated
// back-to-back — the same SENTENCE, whatever the payload's timestamps and ids (four "Signed in with
// a browser cookie" in a row) — becomes one row with its count. Pretty + raw and Raw keep every
// event; only the days are marked.
// INCREMENTALLY, for a log of 100,000 events that grows at both ends (live appends at the tail,
// older pages prepended at the head): `refold` re-folds only the last item and what was appended,
// or the first item and what was prepended, and folds the whole log only when it changed otherwise.
// It equals `foldEvents` over the whole log (folds.test.tsx proves it across appends and prepends).
import { isValidElement, type ReactNode } from "react";
import { isHousekeeping } from "./core-renderers.tsx";
import type { ContextViewEvent, ContextViewMode } from "./types.tsx";

export type FeedItem =
  | { kind: "day"; key: string; date: Date }
  | { kind: "event"; key: string; event: ContextViewEvent }
  /** The same fact several times in a row — shown once, with how many. */
  | { kind: "repeat"; key: string; events: ContextViewEvent[] }
  /** A run of the platform's housekeeping — one quiet row, expandable. */
  | { kind: "housekeeping"; key: string; events: ContextViewEvent[] };

/** The LOCAL calendar day an event fell on — the day the reader's clock says, the same day the
 *  separator labels (feed-rows.tsx); grouping by the UTC date would open a second "Today" for an
 *  evening anywhere east or west of Greenwich. Remembered per event object: a fold asks it of every
 *  event it passes, and a Date per event per fold is most of a 100,000-event fold's time. */
function dayOf(event: ContextViewEvent): string {
  let day = daysSeen.get(event);
  if (!day) {
    day = new Date(event.createdAt).toDateString();
    daysSeen.set(event, day);
  }
  return day;
}
const daysSeen = new WeakMap<ContextViewEvent, string>();

/** What makes two events "the same fact" for the repeat fold. The view keys by the type and the
 *  rendered sentence's text (`sentenceText`); without renderers, by the type and the payload. */
export type FactKey = (event: ContextViewEvent) => string;
export const factByPayload: FactKey = (event) =>
  JSON.stringify([event.type, event.payload ?? null]);

/** The words of a rendered sentence — strings and numbers, elements' children walked — so two
 *  renderings compare as text. Sentences are small trees of spans and strongs; nothing else is expected. */
export function sentenceText(node: ReactNode): string {
  if (node === null || node === undefined || typeof node === "boolean") return "";
  if (typeof node === "string" || typeof node === "number") return String(node);
  if (Array.isArray(node)) return node.map(sentenceText).join("");
  if (isValidElement<{ children?: ReactNode }>(node)) return sentenceText(node.props.children);
  return "";
}

/** Fold `events` into items. `markedDay` is the day already marked above them (a re-fold of the
 *  tail continues the day its first event fell on, so it opens no second separator for it). */
export function foldEvents(
  events: readonly ContextViewEvent[],
  mode: ContextViewMode,
  factOf: FactKey = factByPayload,
  markedDay = "",
): FeedItem[] {
  const items: FeedItem[] = [];
  let lastDay = markedDay;
  let i = 0;
  while (i < events.length) {
    const event = events[i]!;
    const day = dayOf(event);
    if (day !== lastDay) {
      items.push({ kind: "day", key: `day:${day}`, date: new Date(event.createdAt) });
      lastDay = day;
    }
    if (mode === "pretty") {
      if (isHousekeeping(event.type)) {
        let end = i + 1;
        while (
          end < events.length &&
          isHousekeeping(events[end]!.type) &&
          dayOf(events[end]!) === day
        )
          end += 1;
        const run = events.slice(i, end);
        items.push(
          run.length === 1
            ? { kind: "event", key: `event:${String(event.offset)}`, event }
            : { kind: "housekeeping", key: `housekeeping:${String(event.offset)}`, events: run },
        );
        i = end;
        continue;
      }
      const fact = factOf(event);
      let end = i + 1;
      while (end < events.length && dayOf(events[end]!) === day && factOf(events[end]!) === fact)
        end += 1;
      if (end - i >= 2) {
        items.push({
          kind: "repeat",
          key: `repeat:${String(event.offset)}`,
          events: events.slice(i, end),
        });
        i = end;
        continue;
      }
    }
    items.push({ kind: "event", key: `event:${String(event.offset)}`, event });
    i += 1;
  }
  return items;
}

/** Per item, who acted on the last row before it that anyone acted on — "" at the top and after
 *  a day mark (a new day names its first actor again, since yesterday may have scrolled off).
 *  The rows name who acted only when it changes against this. `before` is who acted last above
 *  `items` (a re-fold of the tail carries it on). */
export function whoBefore(
  items: readonly FeedItem[],
  actorOf: (event: ContextViewEvent) => string,
  before = "",
): string[] {
  let last = before;
  return items.map((item) => {
    if (item.kind === "day") {
      last = "";
      return "";
    }
    const before = last;
    const event = lastEventOf(item);
    if (event && actorOf(event)) last = actorOf(event);
    return before;
  });
}

/** The last event an item covers — the anchor for the next row's gap. */
export function lastEventOf(item: FeedItem | undefined): ContextViewEvent | undefined {
  if (!item || item.kind === "day") return undefined;
  return item.kind === "event" ? item.event : item.events.at(-1);
}

/** How many events an item covers. */
const sizeOf = (item: FeedItem): number =>
  item.kind === "day" ? 0 : item.kind === "event" ? 1 : item.events.length;

/** How `next` grew from `previous`, both sorted by offset and `next` holding every element of
 *  `previous` (the SDK's log, a filter of it): the elements added at the end, or at the start —
 *  null when it changed any other way (a filter changed, a window was dropped). Compares the two
 *  ends by identity, which is enough for sorted arrays of distinct elements: if `next` keeps
 *  `previous`'s last element at `previous`'s last index, nothing was added before it. */
export function growthOf<T>(
  previous: readonly T[],
  next: readonly T[],
): { end: readonly T[] } | { start: readonly T[] } | null {
  if (next === previous) return { end: [] };
  if (next.length < previous.length) return null;
  if (previous.length === 0) return { end: next };
  const added = next.length - previous.length;
  if (next[0] === previous[0] && next[previous.length - 1] === previous.at(-1))
    return { end: next.slice(previous.length) };
  if (next.at(-1) === previous.at(-1) && next[added] === previous[0])
    return { start: next.slice(0, added) };
  return null;
}

/** A fold and what it folded, for the next `refold`. */
export type Fold = {
  events: readonly ContextViewEvent[];
  mode: ContextViewMode;
  factOf: FactKey;
  items: FeedItem[];
  /** `whoBefore` of `items`. */
  namedBefore: string[];
};

/** `foldEvents` + `whoBefore` of `events`, re-using `previous` where the log only grew at one
 *  end: an append re-folds the last item (a run the new events may continue) and the new events;
 *  a prepend re-folds the new events and the first item (a run they may extend backwards — the fold
 *  is greedy from the top, so the items after it stand). Anything else folds the whole log. */
export function refold(
  previous: Fold | undefined,
  events: readonly ContextViewEvent[],
  mode: ContextViewMode,
  factOf: FactKey,
  actorOf: (event: ContextViewEvent) => string,
): Fold {
  const growth =
    previous && previous.mode === mode && previous.factOf === factOf && previous.items.length > 0
      ? growthOf(previous.events, events)
      : null;
  if (previous && growth && "end" in growth) {
    if (growth.end.length === 0) return { ...previous, events };
    const last = previous.items.at(-1)!; // a day mark is always followed by an item: never a day
    const start = previous.events.length - sizeOf(last);
    const tail = foldEvents(events.slice(start), mode, factOf, dayOf(events[start]!));
    return {
      events,
      mode,
      factOf,
      items: previous.items.slice(0, -1).concat(tail),
      namedBefore: previous.namedBefore
        .slice(0, -1)
        .concat(whoBefore(tail, actorOf, previous.namedBefore.at(-1))),
    };
  }
  if (previous && growth && "start" in growth) {
    const first = previous.items[1]!; // items[0] is the first day's mark
    const seam = foldEvents(events.slice(0, growth.start.length + sizeOf(first)), mode, factOf);
    const items = seam.concat(previous.items.slice(2));
    return { events, mode, factOf, items, namedBefore: whoBefore(items, actorOf) };
  }
  const items = foldEvents(events, mode, factOf);
  return { events, mode, factOf, items, namedBefore: whoBefore(items, actorOf) };
}

// One live state in the processors panel — the core reduce's under the name `core`, a hosted
// facet's under its own — Pretty (fields, pretty-state.tsx; the core reduce read as its tables) or
// Raw (YAML), as the panel's toggle says.
import { CorePrettyState, PrettyFields } from "./pretty-state.tsx";
import type { LiveStateView } from "./types.tsx";
import { SerializedObjectCodeBlock } from "#/components/code-block.tsx";
import { Spinner } from "#/components/ui/spinner.tsx";

export function LiveStateValue({
  state,
  view,
  core,
}: {
  state: LiveStateView;
  view: "pretty" | "raw";
  /** The core reduce: Pretty reads it as its tables. */
  core: boolean;
}) {
  if (state.status === "error")
    return (
      <p data-type="error" className="text-xs text-destructive">
        Live state unavailable: {state.error}
      </p>
    );
  if (state.value === undefined)
    return (
      <p className="flex items-center gap-2 text-xs text-muted-foreground">
        <Spinner /> Connecting…
      </p>
    );
  if (view === "raw")
    return (
      <SerializedObjectCodeBlock data={state.value} showToggle={false} className="max-h-[28rem]" />
    );
  return core ? <CorePrettyState state={state.value} /> : <PrettyFields value={state.value} />;
}

// Who is here: the people who acted on the context, newest first (from the log's stamps), and how
// many live rpc stubs are lent to it right now. One line, text — no badges. And how busy it is:
// `EventRate`, the strip's live metric (the old header's was a latency sparkline).
import { useEffect, useState } from "react";
import { cn } from "cn";
import type { ContextViewEvent, ContextViewPresence } from "./types.tsx";

/** ` · 12/min`: the events of the last minute, from the tail back (the log is sorted), re-counted
 *  every few seconds while there are any so the rate falls when the log goes quiet; nothing when
 *  the minute was quiet. */
export function EventRate({ events }: { events: readonly ContextViewEvent[] }) {
  const [now, setNow] = useState(() => Date.now());
  let count = 0;
  for (let at = events.length - 1; at >= 0; at--) {
    if (now - Date.parse(events[at]!.createdAt) > 60_000) break;
    count += 1;
  }
  useEffect(() => {
    if (count === 0) return;
    const timer = setInterval(() => setNow(Date.now()), 5_000);
    return () => clearInterval(timer);
  }, [count]);
  // a new event restarts the minute from now
  useEffect(() => setNow(Date.now()), [events]);
  if (count === 0) return null;
  return <span title="Events in the last minute">{` · ${String(count)}/min`}</span>;
}

export function PresenceStrip({
  actors,
  rpcStubs,
  className,
  onPick,
}: {
  actors: readonly ContextViewPresence[];
  rpcStubs: readonly string[];
  className?: string;
  /** Narrow the stream to one actor (again clears). */
  onPick?: (actor: string | undefined) => void;
}) {
  const shown = actors.slice(0, 5);
  return (
    <div
      className={cn(
        "flex flex-wrap items-center gap-x-3 gap-y-1 text-xs text-muted-foreground",
        className,
      )}
    >
      {shown.map((who) => (
        <button
          key={who.actor}
          type="button"
          className="truncate hover:text-foreground"
          title={`${who.actor}${who.grant ? ` via ${who.grant}` : ""} · last ${new Date(who.lastSeenAt).toLocaleString()}`}
          onClick={() => onPick?.(who.actor)}
        >
          {who.email || who.actor}
        </button>
      ))}
      {actors.length > shown.length ? <span>+{actors.length - shown.length}</span> : null}
      {rpcStubs.length > 0 ? (
        <span title={rpcStubs.join(", ")}>
          {rpcStubs.length} live {rpcStubs.length === 1 ? "stub" : "stubs"}
        </span>
      ) : null}
    </div>
  );
}

// The Pretty half of the processors panel's Pretty / Raw toggle: a state read as fields instead of
// YAML. `PrettyFields` reads ANY state (a hosted processor's is the app's own shape): its top-level
// fields one line each, a nested object one level in, a long list folded behind its count.
// `CorePrettyState` reads the core reduce (core/os `CoreState`): where the context is, its rewrite
// rules, schedules, fetch routes and open script runs, the pause. Every read is defensive: the state
// crosses the wire untyped, and a shape miss degrades to the generic fields, never a crash.
import type { ReactNode } from "react";
import { isRecord, record } from "./renderer-helpers.tsx";

/** A state as fields, one line each. */
export function PrettyFields({ value, depth = 0 }: { value: unknown; depth?: number }) {
  if (!isRecord(value)) return <PrettyScalar value={value} />;
  const entries = Object.entries(value);
  if (entries.length === 0) return <span className="text-xs text-muted-foreground">empty</span>;
  return (
    <dl className="grid grid-cols-[minmax(0,max-content)_minmax(0,1fr)] gap-x-3 gap-y-0.5 text-xs">
      {entries.map(([key, field]) => (
        <PrettyField key={key} label={key} value={field} depth={depth} />
      ))}
    </dl>
  );
}

function PrettyField({ label, value, depth }: { label: string; value: unknown; depth: number }) {
  return (
    <>
      <dt className="truncate font-mono text-muted-foreground" title={label}>
        {label}
      </dt>
      <dd className="min-w-0">
        <PrettyFieldValue value={value} depth={depth} />
      </dd>
    </>
  );
}

function PrettyFieldValue({ value, depth }: { value: unknown; depth: number }): ReactNode {
  if (Array.isArray(value)) {
    if (value.length === 0) return <span className="text-muted-foreground">none</span>;
    if (value.length <= 8 && value.every((item) => !isRecord(item) && !Array.isArray(item)))
      return <span className="font-mono break-all">{value.map(scalarText).join(", ")}</span>;
    if (depth > 0 && compactJson(value, 200).length <= 100)
      return <span className="font-mono break-all">{compactJson(value, 100)}</span>;
    return (
      <Folded summary={`${value.length.toLocaleString()} ${value.length === 1 ? "item" : "items"}`}>
        <CompactLines items={value.map((item, index) => [`${index}`, item])} />
      </Folded>
    );
  }
  if (isRecord(value)) {
    const size = Object.keys(value).length;
    if (size === 0) return <span className="text-muted-foreground">{"{}"}</span>;
    if (depth === 0) return <PrettyFields value={value} depth={1} />;
    if (compactJson(value, 200).length <= 100)
      return <span className="font-mono break-all">{compactJson(value, 100)}</span>;
    return (
      <Folded summary={`${size.toLocaleString()} ${size === 1 ? "field" : "fields"}`}>
        <CompactLines items={Object.entries(value)} />
      </Folded>
    );
  }
  return <PrettyScalar value={value} />;
}

function PrettyScalar({ value }: { value: unknown }) {
  if (value == null) return <span className="text-xs text-muted-foreground">—</span>;
  const text = scalarText(value);
  return (
    <span className="font-mono text-xs break-all" title={text.length > 200 ? text : undefined}>
      {text.length > 200 ? `${text.slice(0, 199)}…` : text}
    </span>
  );
}

/** A list folded behind its count: opened in place, each entry one compact line. */
function Folded({ summary, children }: { summary: string; children: ReactNode }) {
  return (
    <details>
      <summary className="cursor-pointer text-muted-foreground hover:text-foreground">
        {summary}
      </summary>
      {children}
    </details>
  );
}

/** Up to 50 entries, each `key  {compact json}` on one line; the rest counted. */
function CompactLines({ items }: { items: [string, unknown][] }) {
  return (
    <div className="flex flex-col py-0.5">
      {items.slice(0, 50).map(([key, item]) => (
        <p key={key} className="truncate font-mono" title={compactJson(item, 2000)}>
          <span className="text-muted-foreground">{key}</span> {compactJson(item, 240)}
        </p>
      ))}
      {items.length > 50 ? (
        <p className="text-muted-foreground">+{(items.length - 50).toLocaleString()} more</p>
      ) : null}
    </div>
  );
}

/** The core reduce, read: where the context is, the pause, and each of its tables. The
 *  subscriptions table is the panel's subscriber list, so it is only counted here. */
export function CorePrettyState({ state }: { state: unknown }) {
  if (!isRecord(state) || !("subscriptions" in state)) return <PrettyFields value={state} />;
  const rules = Object.entries(record(state.itxExpressionRewriteRules));
  const schedules = Object.entries(record(state.schedules));
  const routes = Object.entries(record(state.fetchRoutes));
  const runs = Object.entries(record(state.scriptRuns));
  const tables: [string, unknown[]][] = [
    ["rewrite rules", rules],
    ["schedules", schedules],
    ["fetch routes", routes],
    ["open script runs", runs],
  ];
  const empty = tables.filter(([, table]) => table.length === 0).map(([name]) => name);
  const paused = isRecord(state.paused) ? { reason: scalarText(state.paused.reason) } : undefined;
  const facts: [string, unknown][] = [
    ["path", state.path],
    ["project", state.projectId],
    ["created", state.createdAt],
    ["incarnation", state.incarnation],
    ["ingress", state.ingressTarget ? printExpression(state.ingressTarget) : undefined],
  ];
  return (
    <div className="flex flex-col gap-3 text-xs">
      {paused ? (
        <p className="text-amber-700">Paused{paused.reason ? `: ${paused.reason}` : ""}</p>
      ) : null}
      <dl className="grid grid-cols-[minmax(0,max-content)_minmax(0,1fr)] gap-x-3 gap-y-0.5">
        {facts
          .filter(([, value]) => value != null)
          .map(([label, value]) => (
            <PrettyField key={label} label={label} value={value} depth={1} />
          ))}
        <PrettyField
          label="subscriptions"
          value={`${Object.keys(record(state.subscriptions)).length} (listed above)`}
          depth={1}
        />
      </dl>
      {rules.length > 0 ? (
        <CoreTable title="Rewrite rules" count={rules.length}>
          {rules.map(([match, rule]) => {
            const row = record(rule);
            return (
              <p key={match} className="font-mono break-all">
                {match} <span className="text-muted-foreground">→</span>{" "}
                {row.target === null ? "denied" : printExpression(row.target)}
                {typeof row.description === "string" ? (
                  <span className="ml-2 font-sans text-muted-foreground">{row.description}</span>
                ) : null}
              </p>
            );
          })}
        </CoreTable>
      ) : null}
      {schedules.length > 0 ? (
        <CoreTable title="Schedules" count={schedules.length}>
          <CompactLines items={schedules} />
        </CoreTable>
      ) : null}
      {routes.length > 0 ? (
        <CoreTable title="Fetch routes" count={routes.length}>
          <CompactLines items={routes} />
        </CoreTable>
      ) : null}
      {runs.length > 0 ? (
        <CoreTable title="Open script runs" count={runs.length}>
          {runs.map(([offset, run]) => (
            <p key={offset} className="font-mono">
              #{offset}{" "}
              <span className="text-muted-foreground">
                requested {scalarText(record(run).requestedAt)}
              </span>
            </p>
          ))}
        </CoreTable>
      ) : null}
      {empty.length > 0 ? <p className="text-muted-foreground">No {empty.join(", ")}.</p> : null}
    </div>
  );
}

function CoreTable({
  title,
  count,
  children,
}: {
  title: string;
  count: number;
  children: ReactNode;
}) {
  return (
    <div className="flex flex-col gap-0.5">
      <p className="text-muted-foreground">
        {title} <span className="tabular-nums">{count}</span>
      </p>
      {children}
    </div>
  );
}

/** A parsed itx expression as the call it spells: `["itx","builtins",["get","x"],"run"]` →
 *  `itx.builtins.get("x").run`. Anything else, as compact JSON. */
export function printExpression(expression: unknown): string {
  if (typeof expression === "string") return expression;
  if (!Array.isArray(expression)) return compactJson(expression, 240);
  const steps: string[] = [];
  for (const step of expression) {
    if (typeof step === "string") steps.push(step);
    else if (Array.isArray(step) && typeof step[0] === "string")
      steps.push(
        `${step[0]}(${step
          .slice(1)
          .map((arg) => compactJson(arg, 80))
          .join(", ")})`,
      );
    else return compactJson(expression, 240);
  }
  return steps.join(".");
}

function scalarText(value: unknown): string {
  return typeof value === "string" ? value : compactJson(value, 400);
}

function compactJson(value: unknown, max: number): string {
  let text: string;
  try {
    text = JSON.stringify(value, (_key, item: unknown) =>
      typeof item === "bigint" ? item.toString() : item,
    );
  } catch {
    text = String(value);
  }
  text ||= String(value);
  return text.length > max ? `${text.slice(0, max - 1)}…` : text;
}

// The processors panel — everything live about one context, in one right-edge sheet, read top to
// bottom:
// - VITALS: the head, the append rate, the context's age and incarnation, the pause; a sparkline of
//   appends per minute over the last hour (from the loaded log's timestamps: no metric of its own).
// - WHO IS HERE: every principal that acted, newest first, with when (a click narrows the feed to
//   them), and the rpc stubs lent right now.
// - SUBSCRIBERS: every row of the subscriptions table (`itx.subscriptions.list()`), one section each —
//   what it consumes, where it is delivered, since when; a PROCESSOR (a row hosting a facet) with its
//   class, its restarts and its live state; a LIVE CALLBACK (a session's lent stub) connected or not;
//   an ITX CALL with its cursor (confirmed offset, lag, retries) or where it halted.
// - THE CONTEXT: the core reduce's snapshot, and the offset it reduced through.
// One Pretty / Raw toggle for every state here: fields (pretty-state.tsx) or YAML.
import { useEffect, useMemo, useState, type ReactNode } from "react";
import { cn } from "cn";
import { shortEventType } from "./filters.tsx";
import { LiveStateValue } from "./live-state-value.tsx";
import { record } from "./renderer-helpers.tsx";
import type {
  ContextViewEvent,
  ContextViewPresence,
  ContextViewProcessor,
  LiveStateView,
} from "./types.tsx";
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
} from "#/components/ui/sheet.tsx";

export function ProcessorsPanel({
  open,
  onClose,
  processors,
  presence,
  liveState,
  events,
  head,
  onPickActor,
}: {
  open: boolean;
  onClose: () => void;
  /** The subscriptions table: every subscriber; a row hosting a facet is a processor. */
  processors: readonly ContextViewProcessor[];
  presence: { actors: readonly ContextViewPresence[]; rpcStubs: readonly string[] };
  /** Each live state by name — `core`, and every hosted facet's. */
  liveState: Record<string, LiveStateView>;
  /** The loaded log, sorted by offset: the append rate is read off its tail. */
  events: readonly ContextViewEvent[];
  head: number | undefined;
  /** Narrow the feed to one actor. */
  onPickActor: (actor: string) => void;
}) {
  const [view, setView] = useState<"pretty" | "raw">("pretty");
  const now = useNow(open);
  const rpcStubs = useMemo(() => new Set(presence.rpcStubs), [presence.rpcStubs]);
  const subscribers = useMemo(
    () =>
      [...processors].sort(
        (a, b) =>
          kindRank(kindOf(a)) - kindRank(kindOf(b)) || a.configuredAtOffset - b.configuredAtOffset,
      ),
    [processors],
  );
  // the stubs that are a subscriber's live callback show under that subscriber
  const callbackStubs = new Set(subscribers.flatMap((row) => lentStubKey(row) ?? []));
  const otherStubs = presence.rpcStubs.filter((key) => !callbackStubs.has(key));
  const core = liveState.core || CONNECTING;
  const delivered = subscribers.filter((row) => kindOf(row) !== "callback");
  const liveCallbacks = subscribers.filter(
    (row) => kindOf(row) === "callback" && rpcStubs.has(lentStubKey(row)!),
  );
  const orphanedCallbacks = subscribers.filter(
    (row) => kindOf(row) === "callback" && !rpcStubs.has(lentStubKey(row)!),
  );
  return (
    <Sheet open={open} onOpenChange={(next) => !next && onClose()}>
      <SheetContent
        side="right"
        className="overflow-y-auto data-[side=right]:w-full data-[side=right]:sm:max-w-2xl"
      >
        <SheetHeader className="flex-row items-start gap-3">
          <div className="min-w-0 flex-1">
            <SheetTitle>Processors</SheetTitle>
            <SheetDescription>
              Who is here, what subscribes to this context, and what each has folded.
            </SheetDescription>
          </div>
          <div
            role="tablist"
            aria-label="How state reads"
            className="mr-8 flex shrink-0 rounded-md border p-0.5 text-xs"
          >
            {(["pretty", "raw"] as const).map((candidate) => (
              <button
                key={candidate}
                type="button"
                role="tab"
                aria-selected={view === candidate}
                onClick={() => setView(candidate)}
                className={cn(
                  "rounded px-2 py-0.5 capitalize",
                  view === candidate
                    ? "bg-muted text-foreground"
                    : "text-muted-foreground hover:text-foreground",
                )}
              >
                {candidate}
              </button>
            ))}
          </div>
        </SheetHeader>
        <div className="flex min-w-0 flex-col gap-6 px-4 pb-8">
          <Vitals events={events} head={head} core={core.value} now={now} />

          <Section title="Here" count={presence.actors.length}>
            {presence.actors.length === 0 ? (
              <Quiet>Nobody has acted on this context in the loaded log.</Quiet>
            ) : (
              <ul className="flex flex-col">
                {presence.actors.map((who) => (
                  <li key={who.actor}>
                    <button
                      type="button"
                      onClick={() => onPickActor(who.actor)}
                      title={`Show only what ${who.email || who.actor} did`}
                      className="flex w-full min-w-0 items-baseline gap-3 rounded px-1 py-0.5 text-left text-xs hover:bg-muted"
                    >
                      <span className="min-w-0 flex-1 truncate">
                        {who.email || who.actor}
                        {who.email ? (
                          <span className="ml-2 font-mono text-muted-foreground">{who.actor}</span>
                        ) : null}
                      </span>
                      {who.grant ? (
                        <span className="hidden truncate font-mono text-muted-foreground sm:inline">
                          {who.grant}
                        </span>
                      ) : null}
                      <span
                        className="shrink-0 text-muted-foreground tabular-nums"
                        title={who.lastSeenAt}
                      >
                        {ago(who.lastSeenAt, now)}
                      </span>
                    </button>
                  </li>
                ))}
              </ul>
            )}
            <p className="px-1 text-xs text-muted-foreground">
              {presence.rpcStubs.length === 0
                ? "No rpc stub is lent to this context right now."
                : `${presence.rpcStubs.length} rpc ${presence.rpcStubs.length === 1 ? "stub" : "stubs"} lent right now${
                    otherStubs.length < presence.rpcStubs.length
                      ? `, ${presence.rpcStubs.length - otherStubs.length} of them for the live callbacks below`
                      : ""
                  }.`}
            </p>
            {otherStubs.length > 0 ? (
              <ul className="flex flex-col px-1">
                {otherStubs.map((key) => (
                  <li key={key} className="truncate font-mono text-xs" title={key}>
                    {key}
                  </li>
                ))}
              </ul>
            ) : null}
          </Section>

          <Section title="Subscribers" count={subscribers.length}>
            {subscribers.length === 0 ? (
              <Quiet>Nothing subscribes to this context.</Quiet>
            ) : (
              <div className="flex flex-col divide-y">
                {delivered.map((row) => (
                  <Subscriber
                    key={row.name}
                    row={row}
                    head={head}
                    state={row.hostedFacet ? liveState[row.hostedFacet.name] : undefined}
                    view={view}
                  />
                ))}
              </div>
            )}
            {liveCallbacks.length > 0 ? (
              <div className="flex flex-col gap-0.5">
                <p className="text-xs text-muted-foreground">
                  Live callbacks: a session&apos;s subscription, delivered to the stub it lent
                </p>
                {liveCallbacks.map((row) => (
                  <LiveCallback key={row.name} row={row} connected />
                ))}
                {orphanedCallbacks.length > 0 ? (
                  <details className="text-xs">
                    <summary className="cursor-pointer text-muted-foreground hover:text-foreground">
                      {orphanedCallbacks.length} not connected: their session ended and the row
                      stayed
                    </summary>
                    {orphanedCallbacks.map((row) => (
                      <LiveCallback key={row.name} row={row} connected={false} />
                    ))}
                  </details>
                ) : null}
              </div>
            ) : null}
          </Section>

          <Section
            title="The context"
            aside={
              typeof core.rev === "number" ? (
                <span className="tabular-nums">reduced through #{core.rev.toLocaleString()}</span>
              ) : null
            }
          >
            <p className="text-xs text-muted-foreground">
              The core reduce: rewrite rules, subscriptions, schedules, fetch routes, open runs, the
              pause.
            </p>
            <LiveStateValue state={core} view={view} core />
          </Section>
        </div>
      </SheetContent>
    </Sheet>
  );
}

/** One subscriber: a heading line (name, kind, status), its facts as label / value lines, and a
 *  processor's live state under them. */
function Subscriber({
  row,
  head,
  state,
  view,
}: {
  row: ContextViewProcessor;
  head: number | undefined;
  state: LiveStateView | undefined;
  view: "pretty" | "raw";
}) {
  const kind = kindOf(row);
  const status = statusOf(row, kind);
  const lag =
    row.cursor && head !== undefined ? Math.max(0, head - row.cursor.confirmedOffset) : undefined;
  return (
    <section className="flex min-w-0 flex-col gap-1.5 py-3 first:pt-1">
      <div className="flex min-w-0 flex-wrap items-baseline gap-x-2">
        <h4 className="min-w-0 font-mono text-sm font-medium break-all">{row.name}</h4>
        <span className="text-xs text-muted-foreground">{KIND_LABEL[kind]}</span>
        <span className={cn("ml-auto text-xs", status.tone)}>{status.label}</span>
      </div>
      <dl className="grid grid-cols-[minmax(0,max-content)_minmax(0,1fr)] gap-x-3 gap-y-0.5 text-xs">
        <Fact label="consumes">
          <span className="font-mono break-all">{consumesText(row.consumes)}</span>
        </Fact>
        <Fact label="delivers to">
          <span className="font-mono break-all">{row.target}</span>
        </Fact>
        {row.hostedFacet ? (
          <Fact label="hosts">
            <span className="font-mono break-all">
              {row.hostedFacet.className}
              {row.hostedFacet.name === row.name ? "" : ` as ${row.hostedFacet.name}`}
            </span>
            <span
              className={cn(
                "ml-2",
                row.hostedFacet.restarts > 0 ? "text-amber-700" : "text-muted-foreground",
              )}
              title="How often the platform failed the facet at its start and restarted it"
            >
              {row.hostedFacet.restarts > 0
                ? `restarted ${row.hostedFacet.restarts}×`
                : "never restarted"}
            </span>
          </Fact>
        ) : null}
        <Fact label="since">
          <span className="tabular-nums">
            configured at #{row.configuredAtOffset.toLocaleString()}
            {row.afterOffset !== undefined && row.afterOffset !== row.configuredAtOffset
              ? `, delivering after #${row.afterOffset.toLocaleString()}`
              : ""}
          </span>
        </Fact>
        {row.cursor ? (
          <Fact label="confirmed">
            <span className="tabular-nums">
              #{row.cursor.confirmedOffset.toLocaleString()}
              {lag === undefined ? null : (
                <span className={cn("ml-2", lag > 0 ? "text-amber-700" : "text-muted-foreground")}>
                  lag {lag.toLocaleString()}
                </span>
              )}
            </span>
          </Fact>
        ) : null}
        {row.halted ? (
          <Fact label="halted">
            <span className="text-destructive">
              after #{row.halted.afterOffset.toLocaleString()}, {row.halted.attempts} attempts
              {row.halted.error ? `: ${row.halted.error}` : ""}
            </span>
          </Fact>
        ) : null}
      </dl>
      {state ? (
        <div className="flex min-w-0 flex-col gap-1 pt-1">
          <p className="text-xs text-muted-foreground">Live state</p>
          <LiveStateValue state={state} view={view} core={false} />
        </div>
      ) : null}
    </section>
  );
}

/** A session's live callback, one line: its name, what it consumes, whether its stub is lent now. */
function LiveCallback({ row, connected }: { row: ContextViewProcessor; connected: boolean }) {
  return (
    <p className="flex min-w-0 items-baseline gap-3 text-xs" title={row.target}>
      <span className="shrink-0 font-mono">{row.name}</span>
      <span className="min-w-0 flex-1 truncate font-mono text-muted-foreground">
        {consumesText(row.consumes)}
      </span>
      <span className="shrink-0 text-muted-foreground tabular-nums">
        #{row.configuredAtOffset.toLocaleString()}
      </span>
      <span className={cn("shrink-0", connected ? "text-emerald-700" : "text-muted-foreground")}>
        {connected ? "connected" : "gone"}
      </span>
    </p>
  );
}

/** The head, the rate, the age and the pause on one line; a sparkline of the last hour under it. */
function Vitals({
  events,
  head,
  core,
  now,
}: {
  events: readonly ContextViewEvent[];
  head: number | undefined;
  core: unknown;
  now: number;
}) {
  const perMinute = useMemo(() => appendsPerMinute(events, now), [events, now]);
  const lastFive = perMinute.slice(-5).reduce((sum, count) => sum + count, 0) / 5;
  const state = record(core);
  const paused = state.paused ? record(state.paused) : undefined;
  const peak = Math.max(...perMinute);
  return (
    <section className="flex flex-col gap-2">
      <div className="flex flex-wrap gap-x-6 gap-y-2">
        <Stat label="head" value={head === undefined ? "—" : `#${head.toLocaleString()}`} />
        <Stat
          label="appends / min"
          value={lastFive >= 10 ? String(Math.round(lastFive)) : lastFive.toFixed(1)}
          title="Mean over the last five minutes, from the loaded log"
        />
        <Stat
          label="age"
          value={typeof state.createdAt === "string" ? ago(state.createdAt, now, "") : "—"}
          title={typeof state.createdAt === "string" ? `Created ${state.createdAt}` : undefined}
        />
        <Stat
          label="incarnation"
          value={typeof state.incarnation === "number" ? String(state.incarnation) : "—"}
          title="The Durable Object's wake count: growth across idle is hibernation"
        />
        <Stat
          label="paused"
          value={paused ? "yes" : "no"}
          title={typeof paused?.reason === "string" ? paused.reason : undefined}
          tone={paused ? "text-amber-700" : undefined}
        />
      </div>
      <Sparkline counts={perMinute} />
      <p className="text-[11px] text-muted-foreground">
        Appends per minute over the last hour{peak > 0 ? `, peak ${peak}` : ""}, from the loaded
        log.
      </p>
    </section>
  );
}

function Stat({
  label,
  value,
  title,
  tone,
}: {
  label: string;
  value: string;
  title?: string;
  tone?: string;
}) {
  return (
    <div title={title}>
      <div className="text-[10px] tracking-wide text-muted-foreground uppercase">{label}</div>
      <div className={cn("font-mono text-sm tabular-nums", tone)}>{value}</div>
    </div>
  );
}

/** One series as an area and its line, scaled to its own peak (floored at 5, so one event is not
 *  a mountain). */
function Sparkline({ counts }: { counts: readonly number[] }) {
  const width = 360;
  const height = 36;
  const max = Math.max(5, ...counts);
  const step = width / Math.max(1, counts.length - 1);
  const points = counts
    .map(
      (count, index) =>
        `${(index * step).toFixed(1)},${(height - 1 - (count / max) * (height - 4)).toFixed(1)}`,
    )
    .join(" ");
  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      preserveAspectRatio="none"
      className="h-9 w-full text-sky-600"
      aria-hidden
    >
      <polygon points={`0,${height} ${points} ${width},${height}`} className="fill-sky-500/10" />
      <polyline
        points={points}
        fill="none"
        stroke="currentColor"
        strokeWidth="1.25"
        strokeLinejoin="round"
        vectorEffect="non-scaling-stroke"
      />
    </svg>
  );
}

function Section({
  title,
  count,
  aside,
  children,
}: {
  title: string;
  count?: number;
  aside?: ReactNode;
  children: ReactNode;
}) {
  return (
    <section className="flex min-w-0 flex-col gap-2">
      <h3 className="flex items-baseline gap-2 text-xs font-medium tracking-wide text-muted-foreground uppercase">
        {title}
        {count === undefined ? null : <span className="tabular-nums">{count}</span>}
        {aside ? (
          <span className="ml-auto text-xs font-normal tracking-normal normal-case">{aside}</span>
        ) : null}
      </h3>
      {children}
    </section>
  );
}

function Fact({ label, children }: { label: string; children: ReactNode }) {
  return (
    <>
      <dt className="text-muted-foreground">{label}</dt>
      <dd className="min-w-0">{children}</dd>
    </>
  );
}

function Quiet({ children }: { children: ReactNode }) {
  return <p className="text-xs text-muted-foreground">{children}</p>;
}

type Kind = "processor" | "callback" | "call";

const KIND_LABEL: Record<Kind, string> = {
  processor: "processor",
  callback: "live callback",
  call: "itx call",
};

const kindRank = (kind: Kind) => ["processor", "call", "callback"].indexOf(kind);

/** A row hosting a facet is a processor; one delivered to a lent stub is a session's live
 *  callback; anything else is an itx call the context delivers at-least-once. */
function kindOf(row: ContextViewProcessor): Kind {
  if (row.hostedFacet) return "processor";
  return lentStubKey(row) === undefined ? "call" : "callback";
}

/** The key of the rpc stub a row delivers to (`itx.builtins.rpcStubs.get('<key>')…`), if it does. */
function lentStubKey(row: ContextViewProcessor): string | undefined {
  return /rpcStubs\.get\((["'])(.+?)\1\)/.exec(row.target)?.[2];
}

function statusOf(row: ContextViewProcessor, kind: Kind): { label: string; tone: string } {
  if (row.halted) return { label: "halted", tone: "text-destructive" };
  if (row.cursor?.nextAttemptAtMs !== undefined)
    return {
      label: `retrying, attempt ${row.cursor.attempt}`,
      tone: "text-amber-700",
    };
  if (kind === "processor") return { label: "hosted", tone: "text-emerald-700" };
  return { label: "delivering", tone: "text-emerald-700" };
}

/** What a row consumes, short: its types without the `events.iterate.com/` prefix; none or `*` is
 *  every durable event. */
function consumesText(consumes: readonly string[] | undefined): string {
  if (!consumes?.length || consumes.includes("*")) return "every durable event";
  return consumes.map(shortEventType).join(", ");
}

const CONNECTING: LiveStateView = { status: "connecting", value: undefined };

/** Appends per minute over the last hour (60 buckets, oldest first), read backwards off the
 *  loaded log's tail until an event is older than the window. */
function appendsPerMinute(events: readonly ContextViewEvent[], now: number): number[] {
  const counts = Array.from({ length: 60 }, () => 0);
  const start = now - 60 * 60_000;
  for (let index = events.length - 1; index >= 0; index--) {
    const at = Date.parse(events[index]!.createdAt);
    if (Number.isNaN(at)) continue;
    if (at < start) break;
    counts[Math.min(59, Math.floor((at - start) / 60_000))]!++;
  }
  return counts;
}

/** A compact age: `12s`, `5m`, `3.2h`, `4d`, with `suffix` after it. */
function ago(iso: string, now: number, suffix = " ago"): string {
  const seconds = Math.max(0, Math.round((now - Date.parse(iso)) / 1000));
  if (Number.isNaN(seconds)) return "—";
  if (seconds < 60) return `${seconds}s${suffix}`;
  if (seconds < 3600) return `${Math.round(seconds / 60)}m${suffix}`;
  if (seconds < 86_400) return `${(seconds / 3600).toFixed(1)}h${suffix}`;
  return `${Math.round(seconds / 86_400)}d${suffix}`;
}

/** The clock, ticking every 15 s while `running` (the panel is open). */
function useNow(running: boolean): number {
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => {
    if (!running) return;
    setNow(Date.now());
    const timer = setInterval(() => setNow(Date.now()), 15_000);
    return () => clearInterval(timer);
  }, [running]);
  return now;
}

// Payload readers for an `EventRenderers` registry: an event's payload is untyped JSON, and every
// registry (the platform's core-renderers.tsx, the dash's facts, the agents app's log) reads the
// same few shapes out of it and marks ids up the same way.

export const str = (value: unknown, fallback = "") =>
  typeof value === "string" ? value : fallback;

export const list = (value: unknown) => (Array.isArray(value) ? value.map(String) : []);

/** A plain object (the payload's shape): the `toString` brand, so arrays and class instances are not. */
export const isRecord = (value: unknown): value is Record<string, unknown> =>
  Object.prototype.toString.call(value) === "[object Object]";

/** A plain object, else an empty one. */
export const record = (value: unknown): Record<string, unknown> => (isRecord(value) ? value : {});

/** A muted mono span for an id, a path or a name inside a sentence. */
export const mono = (text: string) => (
  <span className="font-mono text-xs text-muted-foreground">{text}</span>
);

// Stick the feed's scroll container to its bottom edge, Slack-style, with plain DOM events — no
// timers, no polling.
//
// Why not TanStack Virtual's followOnAppend/scrollToEnd: they act on the virtualizer's INTERNAL
// offset/size model, which drifts from the real DOM by small amounts while rows settle (its
// isAtEnd() can read true while the viewport sits a row short), and knows nothing of a viewport
// that resizes without a scroll event. This works in DOM truth: whenever the viewport or the
// content resizes while stuck, it writes scrollTop = scrollHeight. The scroll event that write fires
// also re-synchronises the virtualizer's offset, so its own end-anchored compensation for a reader
// mid-history keeps agreeing with reality.
//
// Lifecycle: starts stuck (the feed opens at the newest event). Real user input on the scroller —
// an upward wheel, a touch, a key, a pointer down (a scrollbar grab, a row click) — releases it, so a
// reader in history, or one who clicked a row open, is never yanked. A user scroll that lands back
// at the bottom re-engages it. Releasing on touchstart also means it never writes scrollTop during a
// touch fling (WebKit drops writes during momentum). `stick()` re-engages it from outside — the
// view's own append, which the person wants to see land wherever they were reading; `release()`
// lets go from outside — the feed scrolling to an event the reader stepped to. `stuck` is the same
// fact as React state, set only when it flips, for the "Jump to latest" button.
import { useCallback, useEffect, useRef, useState, type RefObject } from "react";

/** How close (px) to the bottom a user scroll must land to re-engage the stick. */
const RESTICK_EPSILON_PX = 2;

export function useStickToBottom({
  scrollElementRef,
  contentElementRef,
}: {
  scrollElementRef: RefObject<HTMLElement | null>;
  /** The virtualizer's sizer: its resize (appends, late measurements) re-pins the bottom. It may
   *  mount after the scroller (behind an empty state), so it is observed after every render. */
  contentElementRef: RefObject<HTMLElement | null>;
}): { stuckRef: RefObject<boolean>; stuck: boolean; stick: () => void; release: () => void } {
  const stuck = useRef(true);
  const [stuckState, setStuckState] = useState(true);
  const resizeObserverRef = useRef<ResizeObserver | null>(null);

  useEffect(() => {
    const scroller = scrollElementRef.current;
    if (!scroller) return;
    const restick = () => {
      // a direct DOM write, not virtualizer.scrollToEnd(): the target is the real bottom by
      // definition, and this never arms the library's uncancellable multi-frame reconcile loop
      if (stuck.current) scroller.scrollTop = scroller.scrollHeight;
    };
    // fires once per observe (the opening scroll to the bottom), then on every observed resize
    const resizeObserver = new ResizeObserver(restick);
    resizeObserverRef.current = resizeObserver;
    resizeObserver.observe(scroller);
    if (contentElementRef.current) resizeObserver.observe(contentElementRef.current);
    const release = (event: Event) => {
      if (!stuck.current) return;
      // a breadcrumb: a released stick is the first suspect when a feed strands mid-history
      console.debug(`[stick-to-bottom] released: user-input:${event.type}`);
      stuck.current = false;
      setStuckState(false);
    };
    // only an UPWARD wheel leaves the tail: wheeling down at the bottom would release into a dead
    // state where the next append writes nothing and no scroll event fires to re-stick
    const onWheel = (event: WheelEvent) => {
      if (event.deltaY < 0) release(event);
    };
    const onScroll = () => {
      if (stuck.current) return;
      const distance = scroller.scrollHeight - scroller.clientHeight - scroller.scrollTop;
      if (distance > RESTICK_EPSILON_PX) return;
      stuck.current = true;
      setStuckState(true);
    };
    const releaseEvents = ["touchstart", "keydown", "pointerdown"] as const;
    for (const name of releaseEvents) scroller.addEventListener(name, release, { passive: true });
    scroller.addEventListener("wheel", onWheel, { passive: true });
    scroller.addEventListener("scroll", onScroll, { passive: true });
    return () => {
      resizeObserver.disconnect();
      resizeObserverRef.current = null;
      for (const name of releaseEvents) scroller.removeEventListener(name, release);
      scroller.removeEventListener("wheel", onWheel);
      scroller.removeEventListener("scroll", onScroll);
    };
  }, [scrollElementRef, contentElementRef]);

  // observe() on an already-observed target is a spec'd no-op, so this is idempotent and cheap
  useEffect(() => {
    if (contentElementRef.current) resizeObserverRef.current?.observe(contentElementRef.current);
  });

  const stick = useCallback(() => {
    stuck.current = true;
    setStuckState(true);
    const scroller = scrollElementRef.current;
    if (scroller) scroller.scrollTop = scroller.scrollHeight;
  }, [scrollElementRef]);

  const release = useCallback(() => {
    stuck.current = false;
    setStuckState(false);
  }, []);

  return { stuckRef: stuck, stuck: stuckState, stick, release };
}

// The context view's vocabulary: a committed event as the view reads it (structural — the itx
// envelope is a superset), the renderers an app plugs in per event type, and the rows the panels
// show. Pure types: this directory renders data the SDK's hooks (`iterate/react`) hand it.
import type { ReactNode } from "react";

export type ContextViewEvent = {
  offset: number;
  type: string;
  createdAt: string;
  payload?: unknown;
  metadata?: Record<string, unknown>;
  idempotencyKey?: string;
  /** Where it came from, as the platform stamped it (core/os/src/caller.ts `stampCaller`). */
  source?: {
    /** The context whose code or session wrote it. */
    origin?: string;
    principal?: { actor: string; email?: string };
    grant?: string;
    processor?: { slug: string; version: string };
    /** The platform wrote this fact on the principal's behalf (core/os/src/caller.ts `Caller.platform`). */
    platform?: true;
    /** Why it happened (core/os/src/cause.ts): the chain it belongs to, `<ISO> with <origin>
     *  ~<nonce>`, how deep in it, and the event whose handling wrote it. */
    cause?: { chain: string; depth: number; parent?: string };
  };
};

/** How the log reads: `pretty` — one sentence per event (the platform's own
 *  events come with theirs; an app adds its vocabulary; a type nobody names shows the type and a
 *  glance at the payload's fields), the platform's housekeeping folded into one quiet row, a fact
 *  repeated back-to-back shown once with its count; `pretty-raw` — every event, its sentence and
 *  its raw line; `raw` — the type and the payload's JSON, one line each, the log as data. */
export type ContextViewMode = "pretty" | "pretty-raw" | "raw";

/** A rich rendering of one event's body — what the row shows instead of the type and the payload
 *  preview. Return null to fall back to the default row. */
export type EventRenderer = (event: ContextViewEvent) => ReactNode | null;

/** Renderers by event type: an exact type, or a prefix ending in `*` — the most specific wins. */
export type EventRenderers = Record<string, EventRenderer>;

/** A rich body for one event in the inspector — the message as prose, the script as code, the
 *  model's answer — shown above the envelope and the raw JSON. Return null for the default. */
export type EventInspector = (event: ContextViewEvent) => ReactNode | null;

/** Inspectors by event type, matched like renderers. */
export type EventInspectors = Record<string, EventInspector>;

/** The entry of a by-type registry (renderers, inspectors) for a type: the exact type, else the
 *  longest prefix pattern (`events.iterate.com/agent/*`) that matches. */
export function rendererFor<T>(
  registry: Record<string, T> | undefined,
  type: string,
): T | undefined {
  if (!registry) return undefined;
  if (registry[type]) return registry[type];
  let best: { prefix: string; entry: T } | undefined;
  for (const [pattern, entry] of Object.entries(registry)) {
    if (!pattern.endsWith("*")) continue;
    const prefix = pattern.slice(0, -1);
    if (type.startsWith(prefix) && (!best || prefix.length > best.prefix.length))
      best = { prefix, entry };
  }
  return best?.entry;
}

/** One row of the context's subscriptions table (`itx.subscriptions.list()`): a subscriber; one
 *  that hosts a facet is a processor. */
export type ContextViewProcessor = {
  name: string;
  target: string;
  consumes?: string[];
  configuredAtOffset: number;
  /** Where cursor delivery starts (absent = from `configuredAtOffset`). */
  afterOffset?: number;
  hostedFacet?: { name: string; className: string; cacheKey?: string; restarts: number };
  /** A row delivered at-least-once: the offset the last acked call confirmed, the retry attempt. */
  cursor?: { confirmedOffset: number; attempt: number; nextAttemptAtMs?: number };
  /** Delivery gave up after its retries. */
  halted?: { afterOffset: number; attempts: number; error?: string };
};

/** Who acted on the context, newest first, from the log's stamps. */
export type ContextViewPresence = {
  actor: string;
  email?: string;
  grant?: string;
  lastSeenAt: string;
};

/** One live state as the processors panel renders it (the SDK's `LiveStateResult`, structurally). */
export type LiveStateView = {
  status: string;
  value: unknown;
  /** The revision the value is at: `core`'s is the offset its snapshot reduced through. */
  rev?: number | null;
  error?: string;
};
